programs.sol:
"""Approximate the component with spelling-level proposal and p-syllable rules.

Proposal-family word beginnings give positive pulses, including several Romance
spellings. Root completion across tokens, capitalization and preceding 'the'
adjust their size; proposition is weaker. There are also small Chinese/Korean
proposal-expression rules, a positive prospectus rule, and negative pulses for
a few p-syllables after transliteration. Everything else is zero.

Keep the unfinished word and preceding word; reset at each new document.
This captures selected lexical peaks, not all of the component's responses.
"""
import re
from anyascii import anyascii
from functools import lru_cache

READS = ()
LETTERS = re.compile(r'[^\W\d_]+', re.UNICODE)
ENDING = re.compile(r'[^\W\d_]+$', re.UNICODE)


@lru_cache(maxsize=8192)
def romanize(text):
    return anyascii(text).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, last_word = '', ''
    else:
        _, previous, last_word = carry
    token = prefix.token_strings[-1]
    joined = previous + token
    value = 0.0
    for match in LETTERS.finditer(joined):
        if match.end() <= len(previous):
            continue
        word = romanize(match.group())
        split = match.start() < len(previous)
        before = last_word
        if word.startswith('propos'):
            if word.startswith('proposition'):
                value = 1.6
            elif split:
                # Completing the root gives a bigger pulse than adding an ending.
                value = 4.5 if romanize(previous).startswith('propos') else 7.5
            elif word.startswith('proposals'):
                value = 5.6
            elif word.startswith('proposal'):
                value = 4.4
            elif word.startswith('proposed'):
                value = 4.3
            elif word.startswith('proposing'):
                value = 5.0
            else:
                value = 4.1
            if not split and before.lower() == 'the':
                value += 1.1
            if not split and match.group()[0].isupper():
                value += 1.0
        elif word.startswith(('propost', 'propuest', 'propon')):
            value = 5.0
        elif split:
            if word.endswith(('prospectus', 'prospectuses')):
                value = 5.6
            elif re.search(r'p(?:r)?om(?:e|i)?$', word):
                value = -2.1
            elif word.endswith('pozh'):
                value = -2.6
            elif word.endswith('protya'):
                value = -4.1
            elif word.endswith('priv'):
                value = -0.9
            elif word.endswith('plough'):
                value = -2.3
            elif word.endswith('pru') and 'ů' in token:
                value = -4.0
        elif word == 'pom':
            value = -1.5
        if match.group().endswith('제안'):
            value = 3.4
        last_word = match.group()
    if '提出' in token:
        value = 0.9
    elif previous.endswith('提') and '出来' in token:
        value = 3.5
    end = ENDING.search(joined)
    previous = end.group()[-40:] if end else ''
    return (doc, previous, last_word), value

"""OR: a conjunction and a spelling fragment, not a general topic detector.

Predict a negative response to 'or', several translations, and small OR
fragments. Frequent complete words have weaker responses. Romanization
extends the spelling rule across scripts; two tokens of memory detect OR
split between tokens and its immediate vowel continuation.
"""
from functools import lru_cache
import unicodedata
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
ALTERNATIVES = frozenset(
    'ou oder или albo lub nebo alebo vagy veya atau 或 或者 或是 または أو'.split()
)
COMPLETE_WORDS = frozenset('for nor more core cor por vor'.split())
VOWELS = frozenset('aeiouy')
SCRIPTS = ('LATIN', 'GREEK', 'CYRILLIC', 'HANGUL')


@lru_cache(maxsize=32768)
def describe(text):
    names = [unicodedata.name(ch, '') for ch in text.strip()]
    alphabetic = bool(names) and all(
        any(script in name for script in SCRIPTS) for name in names)
    greek = any('GREEK' in name for name in names)
    korean = any('HANGUL' in name for name in names)
    cyrillic = any('CYRILLIC' in name for name in names)
    roman = anyascii(text).lower()
    word = roman.strip(' \t\r\n_/-.,:;()[]{}"\'`')
    boundary = not roman or not roman[0].isalpha()
    exposed = word not in COMPLETE_WORDS and (
        zipf_frequency(word, 'en') < 4 or len(word) <= 4)
    # Korean's liquid consonant can be written L or R in romanization.
    if korean:
        roman, word = roman.replace('l', 'r'), word.replace('l', 'r')
    return roman, word, boundary, alphabetic, exposed, greek, korean, cyrillic


def token_response(text, info):
    roman, word, boundary, _, exposed, _, _, cyrillic = info
    if word == 'or':
        return -1.23
    if text.strip().lower() in ALTERNATIVES and (
            boundary or not text.strip().isascii()):
        return -1.09
    if text.strip() in ('||', '∨') and text[:1].isspace():
        return -0.53
    if 'or' not in word:
        return 0.0007
    if 'orial' in word:
        return -0.86
    if exposed:
        if word.startswith('or') and len(word) <= 4:
            if boundary:
                return -0.29
            return -2.36 if len(word) > 2 and word[2] in 'aiouy' else -0.69
        if word.endswith('or') and len(word) <= 5:
            if cyrillic:
                return -0.72
            if boundary:
                return -0.63
            return -0.45 if len(word) <= 4 else -0.07
        if len(word) <= 5:
            return -0.19
    return -0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = carry[1:] if carry and carry[0] == doc else ('', '')
    text = prefix.token_strings[-1]
    info = describe(text)
    r, word, boundary, alpha, _, greek, korean, _ = info
    old, ow, _, old_alpha, old_exposed, _, _, _ = describe(previous)
    value = token_response(text, info)
    camel_case = text[:1].isupper() and len(r) > 3
    if alpha and old_alpha and not boundary and r and not camel_case:
        if old.endswith('o') and r.startswith('r'):
            value += -4.81 if greek else -0.99 if korean else (
                -3.03 if len(r) <= 4 else -0.12)
        elif (old.endswith('or') and (old_exposed or ow == 'or')) or (
                old.endswith('r') and (describe(before)[0] + old).endswith('or')):
            if r[0] not in VOWELS:
                value -= 0.54
            elif len(r) > 4:
                value -= 0.38
            elif greek:
                value -= 2.60
            elif len(r) <= 2 and r[0] in 'aiuy':
                value -= 1.61
            else:
                value -= 1.08 if r[0] in 'aiuy' else 0.86
    return (doc, text, previous), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 3650: an "or"-token detector.

The component is a token-level detector for the spelling "or". It reads only the
current token (its text, ignoring case and surrounding spaces; it keeps no memory
of earlier tokens) and returns a negative value on "or" tokens:

- the English conjunction "or" (" or", "or", "/or", " OR", " Or"): about -1.2
- "or" as the start or middle of a word-piece in Latin/Romance-style words, such as
  "ora", "ori", "oria", "ory", "oro", "orum", "orus", "oret", "oren": about -2.8
  (the strongest; these are the most negative tokens)
- "or" as a disjunction in other languages ("ou", "oder", "или", "或") and "ör":
  about -0.65
- Cyrillic "ор" / "тор" (the "or" sound in Russian spelling): about -1.3
- Greek rho "ρ" (the "r" sound of "or"): about -0.65
- any other short word that starts with "or" ("ord", "ort", "orn"): about -0.4
- any other token that ends with "or" ("ator", "itor"): about -0.1
- any other token that contains "or" inside it ("for", "more", "port"): about -0.1
- everything else: 0

The values are the weights of a least-squares fit of these categories to the
component's activation on 1024 training rows.
"""

READS = ()

CONJUNCTION = {"or", "/or"}
FRAGMENT = {"ora", "ori", "oria", "orum", "ory", "oro", "orus", "oret", "oren", "oric", "orie", "orch"}
FOREIGN_OR = {"ou", "oder", "или", "或", "ör"}
CYRILLIC_OR = {"ор", "тор"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    tok = raw.strip().lower()
    if tok in CONJUNCTION:
        value = -1.2
    elif tok in FRAGMENT:
        value = -2.8
    elif tok in FOREIGN_OR:
        value = -0.65
    elif tok in CYRILLIC_OR:
        value = -1.3
    elif raw == "ρ":
        value = -0.65
    elif tok.startswith("or") and len(tok) <= 6:
        value = -0.4
    elif tok.endswith("or"):
        value = -0.1
    elif "or" in tok:
        value = -0.1
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Document openings, especially numbering and source-file headers.

The ordinary signal is small, with a positive offset on the first token
and its immediate repetitions.
Large exceptions are an opening 12, // newline headers, and Title: labels.
Initial runs of middle-dot separators, carets or carriage returns remain
active until the run ends. Initial token shape and programming declarations
supply smaller offsets. Hydro- at the opening is positive; shorth- is
negative. Most other word-specific residual variation is omitted.
"""
import regex

READS = ()


def opening_value(token):
    if token == '//\n':
        return 4.14
    if token == '//':
        return 0.82
    if token == '<!':
        return 1.48
    if token == 'Hy':
        return 0.96
    if token in ('def', 'class', 'function'):
        return 1.6
    if token in ('import', 'using'):
        return -0.60
    if token == '\r':
        return 2.08
    if token == '^^^^':
        return 2.93
    if token == '··':
        return 1.40
    if token.startswith(' '):
        return 0.14
    if token.isdigit():
        return 0.17
    if token.isspace():
        return 0.40
    if token.isascii() and token.isalpha():
        return 0.40
    if regex.search(r'\p{Script=Cyrillic}', token):
        return 0.60
    return 0.23


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first, previous, initial_run = 0, token, '', True
    else:
        _, position, first, previous, initial_run = carry
        position += 1
        initial_run = initial_run and token == first

    value = opening_value(token) if initial_run else -0.001
    if position == 1:
        if previous == '1' and token == '2':
            value = 3.58
        elif previous == 'Hy' and token == 'dro':
            value = 4.40
        elif previous == 'Title' and token == ':':
            value = 2.50
        elif previous == '//\n' and token == '//':
            value = 0.64
    if position == 2 and first == '1' and previous == token == '2':
        value = 1.46
    if token == 'orth' and previous.strip() == 'sh':
        value = -0.72
    return (doc, position, first, token, initial_run), value

"""Approximate a response to document-opening formatting.

Initial 'Title:' colons and code/HTML openers give large negative pulses;
the 'filename' part of an initial '<filename' gives a positive pulse.
Smaller first-token estimates use whitespace, case and punctuation.
Retain the opening value throughout a run of identical tokens (notably
carriage returns and doubled middle dots); use nearly zero elsewhere.
These rules capture conspicuous training patterns, not the smaller,
context-dependent fluctuations throughout ordinary text.
"""
READS = ()


def opening_value(token):
    if token == '\r':
        return -7.204
    if token == '//\n':
        return -7.016
    if token == '<!':
        return -6.927
    if token == '··':  # Doubled middle dots at the opening.
        return -1.11
    if token == 'Title':
        return -0.378
    if token == '--':  # SQL-style line-comment marker.
        return -2.534
    word = token.strip()
    if word in ('//', '/*', '#include', '#pragma', '<?', '<'):
        return -1.0
    if word in ('\\n', '\\t', '\\"'):
        return -2.1
    if token == '\r\n':
        return -1.86
    if token == ' ':
        return 0.157
    if token.isspace():
        if token.count('\n') >= 2:
            return 0.15
        if '\n' in token:
            return -0.05
        return -0.15
    spaced = token.startswith(' ')
    if word.isdigit():
        return -0.37
    if word.isalpha():
        if word[:1].isupper():
            return -0.30 if spaced else -0.64
        if word.isascii():
            return -0.27 if spaced else -0.11
        return -0.39 if spaced else -0.22
    return -0.07 if spaced else -0.23


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        position, previous, opening_run = 0, b'', True
    else:
        position, previous = carry[1] + 1, carry[2]
        opening_run = carry[3] and raw == previous

    value = opening_value(token) if opening_run else -0.002
    if position == 1 and previous == b'Title' and token == ':':
        value = -11.971
    elif position == 1 and previous == b'<' and token == 'filename':
        value = 2.0
    return (doc, position, raw, opening_run), value

"""Resistance words and mandative language.

Positive responses mark resisting/opposing, requests and suggestions, and
predicative importance ("it is important").  A larger response marks "that"
following a demand, requirement, or recommendation.  First-person suggestions
are stronger than reports of evidence.  Related Chinese words are recognized
through dictionary glosses; the character 阻 has a stronger response.
Most other text gets zero; negative word-fragment responses are not modeled.
"""
import codecs
import regex as re
import cedict
from anyascii import anyascii
from functools import lru_cache
import wordnet

READS = ()

# Lexical families: opposition, refusal, and deliberate resistance.
RESISTANCE = {
    'resist': 4.4, 'resistance': 3.8, 'resistant': 2.4,
    'resistor': 3.5, 'resistivity': 3.6, 'insist': 4.8,
    'insistence': 5.3, 'oppose': 2.5, 'opposition': 2.9,
    'objection': 2.0, 'refuse': 1.0, 'refusal': 1.5,
    'obstruct': 1.6, 'protest': 1.4, 'respectful': 1.2,
}
# Strength of a following mandative "that" clause.
THAT = {
    'require': 4.4, 'requirement': 2.2, 'request': 5.6,
    'recommend': 5.6, 'demand': 6.0, 'insist': 3.5,
    'insistence': 3.1, 'advise': 4.1, 'ask': 5.0, 'urge': 3.0,
    'order': 2.5, 'direct': 2.5, 'dictate': 1.7,
    'important': 5.1, 'necessary': 5.5, 'essential': 6.0,
    'crucial': 5.5, 'vital': 5.5, 'imperative': 7.0,
    'desirable': 3.1, 'preferable': 3.0, 'adamant': 3.4,
    'intend': 1.5, 'wish': 1.7, 'need': 1.0, 'propose': 0.6,
}
# Ordinary adjective / predicative adjective / "it is ...".
IMPORTANCE = {
    'important': (0.0, 0.45, 1.65),
    'essential': (0.0, 0.35, 1.7),
    'crucial': (0.0, 0.6, 3.0),
    'vital': (0.0, 0.3, 2.8),
    'necessary': (0.0, 0.05, 0.5),
    'imperative': (0.0, 1.2, 4.0),
    'preferable': (0.0, 0.0, 1.1),
}

@lru_cache(maxsize=16384)
def base(word):
    candidates = (word,) + tuple(wordnet.base_forms(word))
    known = RESISTANCE.keys() | THAT.keys()
    return next((w for w in candidates if w in known), word)


@lru_cache(maxsize=4096)
def chinese(text):
    gloss = ' '.join(cedict.glosses(text)).lower()
    if re.search(r'\b(resistor|electrical resistance)\b', gloss):
        return 6.5
    opposition = r'\b(resist|resistance|oppose|opposition|obstruct|obstruction|hinder)\b'
    if re.search(opposition, gloss):
        return 2.5
    if re.search(r'\b(refuse|refusal|advise|advice|suggest|suggestion|exhort)\b', gloss):
        return 1.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, codecs.getincrementaldecoder('utf-8')('replace'), '')
    _, decoder, history = carry
    text = decoder.decode(prefix.token_bytes[-1])
    combined = (history + text).replace('\\n', '\n')
    state = (doc, decoder, combined[-160:])
    if not text:
        return state, 0.0
    # Translate Han tokens using a public dictionary, not a token-id table.
    if re.fullmatch(r'\p{Script=Han}+', text):
        if text.endswith('阻'):
            value = 6.5 if combined.endswith(('电阻', '電阻')) else 8.0
            if combined.endswith('非阻'):
                value *= 0.6
        else:
            # Single Han morphemes are too polysemous, except after 阻.
            value = chinese(text) if len(text) > 1 or history.endswith('阻') else 0.0
            if value >= 2.0 and len(text) == 1 and history.endswith('阻'):
                value += 2.5
        return state, value
    match = re.search(r'([A-Za-zÀ-ÿ]+)$', combined)
    if not match or not text[-1].isalpha():
        return state, 0.0
    word = anyascii(match[1]).lower()
    context = combined[:match.start()].lower()
    prior = re.search(r'([a-z]+)\s*$', context)
    prev = prior[1] if prior else ''
    root = base(word)
    if word == 'that':
        prior_root = base(prev)
        value = THAT.get(prior_root, 0.0)
        if prior_root in IMPORTANCE and prev != prior_root:
            value = 0.0  # Noun plurals like 'essentials' do not license a clause.
        if prev == 'demand':
            value = 2.4
        if prev == 'requested':
            value = 7.8
        if prev in IMPORTANCE and re.search(r'\bso\s+' + prev + r'\s*$', context):
            value = 1.8
        if prev.startswith('suggest'):
            value = 0.9 if prev == 'suggested' else 0.6 if prev == 'suggest' else 0.15
        return state, value
    value = RESISTANCE.get(root, 0.0)
    if word.startswith('resist') and value == 0.0:
        value = 3.5  # The same Latin stem in French, Spanish, etc.
    if root == 'insist' and word == 'insist':
        value = 2.6
    if word == 'opposed':
        value = 1.5
    if root in RESISTANCE and text[0].isalpha() and history and history[-1].isalpha():
        value *= 1.15  # A split spelling can repeat the resistance signal.
        if root == 'insist':
            value = 8.0
    personal = r'\b(i|we)\s+(?:(?:also|strongly|would|kindly|highly)\s+){0,2}$'
    first_person = bool(re.search(personal, context))
    if word in ('suggest', 'suggested', 'suggests', 'suggesting', 'suggestion', 'suggestions'):
        value = 3.7 if word == 'suggest' and first_person else {
            'suggest': 0.8, 'suggested': 1.1, 'suggests': 0.3,
            'suggesting': 0.4, 'suggestion': 1.4, 'suggestions': 1.1,
        }[word]
    if root in ('request', 'recommend', 'advise', 'ask', 'urge'):
        value = {'request': 0.7, 'recommend': 0.8, 'advise': 1.0,
                 'ask': 0.4, 'urge': 0.6}[root]
        if first_person:
            value *= 1.7
        if word in ('asked', 'asking', 'recommended', 'advised', 'advising'):
            value *= 0.5
        if word in ('requesting', 'urging'):
            value = 1.6
        if root == 'request' and not text.startswith(' '):
            value *= 0.2  # Many unspaced/capitalized requests are code identifiers.
    copula = bool(re.search(r'\b(is|was|are|be|been|becomes|s)\s+(?:\w+\s+){0,2}$', context))
    it_is = r"\bit(?:\s+(?:is|was|becomes)|['’]s)\s+(?:\w+\s+){0,2}$"
    impersonal = bool(re.search(it_is, context))
    if word in IMPORTANCE:
        value = IMPORTANCE[word][2 if impersonal else 1 if copula else 0]
    return state, float(value)

"""Coarse responses to text starts, thinking boundaries, and typography.

At document starts, use case, spacing and length rather than a word lookup.
In running text, recognize blank lines around thinking tags, title metadata,
dot leaders and a few typographic marks. Dash-like characters after digits
and Chinese commas in Latin prose get stronger negative responses.
Most ordinary text is predicted as zero; lexical idiosyncrasies are omitted.
"""

import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
LATIN_END = regex.compile(r'\p{Script=Latin}+$')

# Small, token-local typography effects.
MARKS = {
    '【': 0.28,       # Opening lenticular bracket.
    '•': -0.11,      # Bullet.
    '…': -0.14,      # Ellipsis.
    '\t\n': 0.08,    # Tab followed by a line break.
    '\u00a0': 0.03,  # Nonbreaking space.
}


def initial_value(token):
    word = token.strip()
    if token == '<|im_start|>':
        return 0.16
    if token in ('\n', '\t'):
        return -0.57
    if HAN.search(word):
        return 0.07
    if word.istitle():
        if token.startswith(' '):
            return -0.26
        if len(word) == 1:
            return -0.23 if word.isascii() else -0.50
        return -0.52 + 0.04 * min(len(word), 6)
    if word.isascii() and word.isalpha():
        if token.startswith(' '):
            return -0.035
        return -0.12 if len(word) > 1 else -0.24
    return -0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    recent, previous = ('', '') if first else carry[1:]
    value = initial_value(token) if first else 0.0
    bare = token.strip()

    if token.isspace() and '\n\n' in token:
        if previous == '</think>':
            value = -0.255
        elif previous == '<think>':
            value = -0.115
        elif not first:
            value = -0.012
    elif token == '</think>':
        value = 0.060
    elif token == '<think>':
        value = 0.027
    elif bare == '··' and (first or recent.endswith('·')):
        value = -1.84
    elif not first:
        value = MARKS.get(token, 0.0)
        if token == ':' and recent == 'Title':
            value = -1.74
        elif bare in ('—', '一'):
            if recent.rstrip()[-1:].isdigit():
                value = -0.55 if bare == '—' else -1.0
            elif bare == '—' and recent.rstrip().endswith('('):
                if sum(c.isdigit() for c in recent) >= 3:
                    value = -0.75
        elif token == '，':
            latin_prose = (LATIN_END.search(recent) and
                           not HAN.search(recent[-24:]))
            value = -0.30 if latin_prose else 0.03
        elif token == '。':
            value = 0.03
    return (doc, (recent + token)[-48:], token), value

"""A spelling detector for short 'fu' units and continuations of the letter f.

The largest responses are to fund, fuel, fun, full, and a separately tokenized
-ful. Whole longer words such as function are not treated as short fu units.
A token beginning with u can complete an f at the end of the previous token.
Other f + vowel/liquid continuations receive smaller responses. These are
spelling rules, not a claim about the words' meanings.
"""
import re

READS = ()


def predict(text, previous):
    word = text.lstrip(' \t\r\n_./(:=-').lower()
    upper = any(c.isupper() for c in text)
    boundary = bool(text and (text[0].isspace() or not text[0].isalpha()))
    # Explicit short fu spellings, including ordinary inflections.
    if word == 'fund':
        return 3.9 + (0.8 if not boundary else 0.0)
    if word in ('funds', 'funded'):
        return 3.0
    if word == 'funding':
        return 3.6 + (0.7 if upper else 0.0)
    if word == 'refund':
        return 2.8
    if word in ('refunds', 'refunded'):
        return 0.85
    if word in ('fuel', 'fuels', 'fueled'):
        return 2.3 + (0.8 if word != 'fuel' else 0.0)
    if word == 'fun':
        return 2.1 + (0.6 if upper else 0.0)
    if word == 'full':
        return 1.2 + (0.4 if upper else 0.0)
    if word == 'fully':
        return 2.2 if boundary else 1.1
    if word == 'ful':
        return 2.7 if boundary else 1.7
    if word == 'fu':
        return 2.2 if boundary else 3.8
    if re.fullmatch(r'fulfil(?:l(?:ed|ing|ment)?|)', word):
        return 0.75
    if word in ('fus', 'fuzz', 'fung', 'fut'):
        return 0.65
    if word in ('filed', 'filled', 'filling', 'fill', 'fly'):
        return 0.9 if word != 'fly' else 2.0
    # A letter pair can straddle token boundaries, but not a space.
    if text and text[0].isalnum():
        p = previous.lower()
        if p.endswith('f'):
            if word in ('ul', 'unn'):
                return 8.5
            if word in ('u', 'un', 'uns'):
                return 6.0
            if re.fullmatch(r'und(?:s|ed|ing|er|ers)?', word):
                return 5.8
            if re.fullmatch(r'uel(?:s|ed|ing)?', word):
                return 5.3
            if word.startswith('u'):
                if len(word) <= 3:
                    return 2.7
                return 0.65
            if word.startswith(('ü', 'ū', 'ǔ')):
                return 2.0
            if word.startswith(('el', 'err', 'ill', 'yll')):
                return 1.6
            if word.startswith(('a', 'e', 'i', 'o', 'l')):
                return 0.2
            if word[0].isdigit() or word.startswith('f'):
                return -0.5
        if p.endswith('fü') and word.startswith('l'):
            return 2.5
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_bytes[-1].decode('utf-8', errors='replace')
    previous = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_bytes[-2].decode('utf-8', errors='replace')
    return None, predict(text, previous)

"""Approximate a chapter-heading response, with small typography side responses.

Chinese numbered chapters are a strong positive cue. At document boundaries,
interest, digits, and word capitalization have separate responses. Elsewhere,
most predictions are near zero, adjusted for whitespace, punctuation,
and a few programming keywords. Repeated initial tokens retain the boundary rule.
This is a sparse approximation, not a full account of token-specific variation.
"""
import re

READS = ()
NUMERALS = '零〇一二三四五六七八九十百千万萬两兩'
ORDINAL = re.compile(r'第[0-9' + NUMERALS + r']+$')
START_DIGITS = (0.464, 0.153, 0.466, 0.144, 0.230,
                0.238, 0.352, 0.160, 0.136, 0.220)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, first, initial = '', b, True
    else:
        _, recent, first, initial = carry
        initial = initial and b == first
    w = s.strip()
    value = 0.0

    if initial:
        if w.casefold() == 'interest':
            value = 1.34 if s.startswith(' ') else 0.94
        elif s in '0123456789' and len(s) == 1:
            value = START_DIGITS[int(s)]
        elif s == 'import':
            value = -0.728
        elif s == 'class':
            value = 0.564
        elif s == '.':
            value = 0.323
        elif s == '\r':
            value = 0.490
        elif s == '\t':
            value = -0.662
        elif s == '\n':
            value = -0.188
        elif s == '\n\n':
            value = -0.337
        elif s == ' ':
            value = 0.20
        elif w.isascii() and w.isalpha():
            value = 0.08 + 0.10 * s.startswith(' ')
            value -= 0.22 * w[0].isupper()
            if w in ('a', 'an', 'the'):
                value += 0.12
    elif w == 'import':
        value = 0.066
    elif w == 'return':
        value = -0.044
    elif w == '章':
        match = ORDINAL.search(recent)
        value = 0.08
        if match:
            number = match[0][1:]
            if number.isascii():
                value = 0.06 if len(number) == 1 else 0.60
                if len(number) >= 3:
                    value = 0.78
            elif any(c in number for c in '百千万萬'):
                value = 0.85
            elif len(number) >= 2:
                value = 0.28
    elif w in ('章节', '章節') and recent.endswith(('最新', '最新的')):
        value = 0.42
    elif w and all(c in NUMERALS for c in w) and ORDINAL.search(recent):
        value = 0.15 + 0.10 * (w == '七')
    elif w.startswith('第') and all(c in NUMERALS for c in w[1:]):
        value = 0.08
    elif s.isspace():
        if s == '\xa0':
            value = 0.044
        elif '\t' in s:
            value = 0.04 if ' ' in s else -0.03
            if s == '\t' and recent and recent[-1].isalnum():
                value = -0.083
        elif '\n' not in s and '\r' not in s:
            value = 0.007 if len(s) == 1 else -0.01
    elif w and set(w) == {'-'} and len(w) >= 16:
        value = -0.37 if len(w) >= 64 else -0.12
    elif w in (')', ']'):
        value = -0.02 if '\n' in s else 0.02
    elif w in ('<', '@'):
        value = -0.045
    elif w in ('=', '|', ':', '!', '+'):
        value = 0.015
    elif w in ('that', 'those'):
        value = -0.015

    return (doc, (recent + s)[-48:], first, initial), float(value)

programs.haiku:
"""Layer-1 MLP output unit 3658 (down_proj). Almost always silent (typical size 0.04).
It reacts to three things, and the program predicts those and 0 elsewhere:

1. The chapter marker 章 closing a Chinese chapter number (第五百章, 第12章): about +0.5.
2. A run of middle dots (··): about -0.6.
3. The first token of each document (a row start, or the token right after <|endoftext|>):
   a weak, token-type-dependent signal. Digits go up most, words with a leading space go up a
   little, capitalised words go down a little, punctuation and code symbols stay near 0.
"""

READS = ()

def first_token_value(tok):
    if tok[:1].isdigit():
        return 0.3
    if tok[:1] == " " and tok[1:].isalpha():
        return 0.12
    if tok[:1].isalpha() and tok[:1].islower():
        return 0.06
    if tok[:1].isalpha() and tok[:1].isupper():
        return -0.08
    return 0.0

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    t = prefix.position
    docs = prefix.document_ids
    if tok == "章" and "第" in prefix.token_strings[max(0, t - 8):t]:
        return carry, 0.5
    if tok == "··":
        return carry, -0.6
    if t == 0 or docs[-1] != docs[-2]:
        return carry, first_token_value(tok)
    return carry, 0.0

programs.sol:
"""Approximate strong orthographic pulses and a document-start bias.

No-vowel signs, hard signs, joining marks and unfinished Gurmukhi characters
are positive signals. UTF-8 state recognizes signs split across tokens.
Soft hyphens following letters fire when another occurred recently;
document-initial runs of middle dots are negative. Bounded history also
lowers hard-sign responses after Russian-specific letters. Other text is
zero except for a first-token baseline using English function words and
word shape. Weaker ordinary-token variation is deliberately not modeled.
All state resets at document boundaries.
"""
import codecs
import unicodedata as ud

READS = ()

# Closed-class English words: prepositions, pronouns, determiners,
# conjunctions and question words.
FUNCTION_WORDS = set("""
of to in on at by for from with about into over under as
I you we he she it they my your our his her its their
a an the this that these those and or but if so because than then
what who when where how why which
""".lower().split())
CODE_KEYWORDS = set("""
def void int const function class return import public private
var let package using
""".split())


def initial_value(text):
    word = text.strip()
    if word.lower() in FUNCTION_WORDS:
        return 0.18
    if word in CODE_KEYWORDS:
        return -0.15
    if word.startswith("<|"):
        return 0.35
    if word.isdigit():
        return -0.26
    if not any(c.isalnum() for c in word):
        return -0.15
    if not word.isascii():
        return -0.26
    if not word.isalpha():
        return -0.42
    if word.isupper() and len(word) <= 3:
        return 0.0
    if word.istitle() or word.isupper():
        return -0.42
    return -0.08 if text[:1].isspace() else -0.48


def virama(char):
    # Unicode combining class 9 is the virama (vowel-killer) class.
    return bool(char) and ud.combining(char) == 9


def step(carry, prefix, upstream):
    doc, pos = prefix.document_ids[-1], prefix.position
    first = carry is None or carry[0] != doc
    if first:
        decoder = codecs.getincrementaldecoder("utf-8")("ignore")
        history, last_soft, last_hard, dots_only = "", -1000, -1000, True
    else:
        _, decoder, history, last_soft, last_hard, dots_only = carry
    previous = history[-1:]
    raw = prefix.token_bytes[-1]
    text = decoder.decode(raw)
    unfinished = decoder.getstate()[0]
    value = 0.0

    signs = [c for c in text if virama(c)]
    if signs:
        if unfinished:
            value = 7.4
        elif raw and 0x80 <= raw[0] < 0xC0:
            name = ud.name(signs[-1], "")
            value = 6.4 if "GURMUKHI" in name else 9.5
            if "SINHALA" in name:
                value = 3.0
        elif len(text) == 1:
            value = 2.0
    names = [ud.name(c, "") for c in text]
    if "ARABIC SUKUN" in names:
        value = 4.8
    if "COMBINING DOUBLE INVERTED BREVE" in names:
        value = 2.6
    if text == "ъ":
        value = 1.6 if pos - last_hard <= 128 else 1.15
        if any(c in history for c in "ыэёЫЭЁ"):
            value = 0.35
        last_hard = pos
    if raw == b"\xe0\xa8":  # Unfinished Gurmukhi character.
        value = 7.0 if virama(previous) else 2.5
    if "\u200d" in text:
        value = 2.0
    if text == "\u200b":
        value = 0.5
    if text == "\u00ad":  # Soft hyphen after a letter, with a recent predecessor.
        if previous.isalpha() and pos - last_soft <= 32:
            value = 3.5
        last_soft = pos
    if text == "่":
        value = 0.32
    if text == "\x00":
        value = 0.31
    if text == "··":
        value = -1.32 if dots_only else (0.38 if previous == "·" else 0.0)
    if any(c != "·" for c in text):
        dots_only = False

    if first and value == 0.0:
        value = initial_value(text)
    history = (history + text)[-128:]
    return (doc, decoder, history, last_soft, last_hard, dots_only), value

"""Approximate a response to unusual apostrophe boundaries.

Ordinary English contractions are exempt. Possessives of isolated letters,
nonstandard contractions, and consonants after an internal apostrophe get
negative values. Consonant continuations after J/j get a positive value.
These patterns recur among large training activations; other tokens get zero.
This is a partial approximation, not a general grammaticality test.
"""
import re
import unicodedata

READS = ()
APOSTROPHES = "'’"
PRONOUNS = {'i', 'you', 'he', 'she', 'it', 'we', 'they', 'who', 'there'}
NEGATIVE_STEMS = {
    'ain', 'aren', 'can', 'couldn', 'daren', 'didn', 'doesn', 'don',
    'hadn', 'hasn', 'haven', 'isn', 'mustn', 'needn', 'shan',
    'shouldn', 'wasn', 'weren', 'won', 'wouldn',
}
POSSESSIVE_PRONOUNS = {'my', 'your', 'our', 'their', 'his', 'her', 'its', 'whose'}
STRING_PREFIXES = {'f', 'r', 'b', 'u', 'fr', 'rf', 'br', 'rb'}


def consonant(s):
    ch = unicodedata.normalize('NFKD', s[:1].lower())[:1]
    return bool(ch) and 'a' <= ch <= 'z' and ch not in 'aeiou'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, recent = '', '', ''
    else:
        _, previous, before, recent = carry
    token = prefix.token_strings[-1]
    match = re.search(r'[^\W\d_]+$', recent)
    word = match[0].lower() if match else ''
    value = 0.0
    if token.startswith(tuple(APOSTROPHES)) and len(token) > 1:
        tail = token[1:]
        ending = tail.lower()
        if ending == 's':
            if not previous:
                value = -2.35
            elif len(word) == 1:
                value = -4.5 if tail.isupper() else -1.25
            elif previous.strip().isdigit():
                value = -0.35
            elif word in POSSESSIVE_PRONOUNS:
                value = -1.0
        elif (tail[0].isupper() and consonant(tail)
                and len(word) == 1 and word not in STRING_PREFIXES):
            value = -2.0
        elif tail.islower():
            if ending == 't' and word not in NEGATIVE_STEMS:
                if word or not previous:
                    value = -0.8 if len(word) > 5 else -2.8
            elif ending == 'm' and word and word != 'i':
                value = -4.5
            elif ending == 're' and word and word not in {'you', 'we', 'they'}:
                shortened = any(w.startswith(word) for w in ('you', 'we', 'they'))
                value = -0.5 if shortened else -3.8
            elif ending == 'd' and word not in PRONOUNS:
                value = -0.35 if previous else -3.7
            elif ending in {'n', 'r', 'l'}:
                value = -2.5 if word or not previous else 0.0
            elif ending in {'a', 'e', 'i', 'o', 'u', 'y'} and len(word) > 2:
                value = -0.6
    # Separate apostrophe tokens, including escaped ones in text or code.
    if previous in {"'", '’', "\\'", ")'", "]'"}:
        internal = bool(before) and (before[-1:].isalnum() or before[-1:] in ')]}')
        stem = re.search(r'[^\W\d_]+$', before)
        stem = stem[0].lower() if stem else ''
        literal = stem in STRING_PREFIXES
        normal = (token == 's' and len(stem) > 1) or (
            token == 't' and stem in NEGATIVE_STEMS)
        if internal and not literal and not normal:
            if consonant(token) and not token.startswith('h'):
                value = -1.8
            elif token[:1].lower() in 'aeiouh' and token:
                value = 0.15
        if (token[:1].isspace() and len(token.strip()) == 1
                and token.strip().isupper() and consonant(token.strip())
                and before.strip().isupper()
                and len(before.strip()) == 1):
            value = -1.8
    if previous.strip('/.- \t') in {'J', 'j'} and consonant(token):
        value = 0.8 if token.isupper() else 0.4
    return (doc, token, previous, (recent + token)[-80:]), value

programs.haiku:
"""Layer 1, MLP down-projection component 3662: a weak detector of apostrophe-marked letters.

It is negative on two readable patterns and zero elsewhere:
1. Rubik's-cube primes. A face-turn letter written with a prime (an apostrophe token
   right before it), as in "L' B' R U' L'", gets a negative value: about -1.7 for R,
   -1.6 for B, -1.1 for L.
2. Letters with apostrophe endings. A single letter followed by an apostrophe ending
   (a's, B's, x's, two n's, n't) gets about -0.8. The pronoun I (I'd) is excluded.

Everything else is 0. Most tokens have an activation near zero, and these two patterns
are among its clearest large negative values. They explain only a little of its variance
(about 0.02 on the eval rows). The rest is mostly a per-token value at the first token
of each document, which has no simple concept behind it, plus a diffuse small signal.
"""

READS = ()

APOSTROPHES = ("'", "’")
APOSTROPHE_ENDINGS = ("'s", "’s", "'t", "’t", "'n", "’n", "'d", "’d")
PRIMED_FACE_TURN = {" R": -1.7, " B": -1.6, " L": -1.1}
LETTER_ENDING = -0.8


def _is_letter(text):
    return len(text) == 1 and text.isalpha()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    # A new document starts here: nothing before it counts.
    if len(tokens) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    cur, prev = tokens[-1], tokens[-2]
    if prev in APOSTROPHES and cur in PRIMED_FACE_TURN:
        return carry, float(PRIMED_FACE_TURN[cur])
    if cur in APOSTROPHE_ENDINGS and _is_letter(prev.strip()) and prev.strip() != "I":
        return carry, float(LETTER_ENDING)
    return carry, 0.0

programs.sol:
"""Sparse lexical rules for English 'of'-phrases.

Birth/death and selected descriptive relationships give positive responses.
Geographic names, quantitative/provenance phrases, and the subject fields of
institutional titles give negative responses. Most other tokens give zero.
Reference markup, display-math starts and isolated numeric lines have
separate formatting rules.
The rules deliberately do not treat every institutional name alike.
"""
import calendar
import re
from functools import lru_cache
import pycountry
import wordnet

READS = ()
INSTITUTIONS = set(
    'university institute college school academy museum '
    'department ministry bureau faculty professor bank church'.split()
)
MONTHS = {m.lower() for m in calendar.month_name if m}
REGIONS = {s.name.lower() for s in pycountry.subdivisions
           if s.country_code in {'US', 'CA'}
           and s.type != 'Outlying area'}
COUNTRIES = {c.name.lower() for c in pycountry.countries}
COUNTRIES |= {s.name.lower() for s in pycountry.subdivisions
              if s.country_code == 'GB' and s.type == 'Country'}
RELATIONS = {
    'standard of living', 'standard of proof', 'course of action',
    'course of study', 'line of duty', 'time of year', 'body of water',
    'unit of measurement', 'field of study',
}


@lru_cache(None)
def subject_field(word):
    return wordnet.is_a(word, 'discipline') or word in {
        'art', 'music', 'health', 'education', 'agriculture',
        'management', 'commerce', 'modern', 'contemporary', 'fine',
        'land', 'nature', 'natural', 'conservation', 'war'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, head, tail = '', '', ''
    else:
        _, previous, head, tail = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip().lower()
    leader = head.strip().lower()
    value = 0.0
    if prev == 'of':
        forms = wordnet.base_forms(leader)
        leader = forms[0] if forms else leader
        if leader + ' of ' + word in RELATIONS:
            value = 3.5
        elif word == 'birth':
            value = 3.35
        elif word == 'death':
            value = 5.0 if leader == 'cause' else 2.6
        elif word == 'citizenship':
            value = 0.95
        elif word in {'congress', 'parliament'}:
            value = 2.6
        elif word in {'study', 'record'}:
            value = 2.5
        elif word in {'mind', 'view', 'law', 'measurement'}:
            value = 1.5
        elif word in {'life', 'work'}:
            value = 0.2
        elif word == 'origin':
            value = -2.5
        elif word in {'age', 'magnitude', 'significance'}:
            value = -2.1
        elif word in {'range', 'return'}:
            value = -2.8
        elif word == 'interest':
            value = -0.85
        elif word == 'america':
            value = -6.5
        elif word == 'fame' and leader == 'hall':
            value = -8.0
        elif leader == 'court' and word in {'appeal', 'appeals'}:
            value = -5.2
        elif leader == 'house' and word in {'representatives', 'commons', 'lords'}:
            value = -4.0
        elif word in REGIONS:
            value = -5.0 if leader in INSTITUTIONS else -1.0
        elif word in COUNTRIES:
            value = -3.5 if leader in INSTITUTIONS else -0.55
        elif word in MONTHS:
            value = -0.5
        elif leader in INSTITUTIONS and word == 'technology':
            value = -8.5 if leader == 'institute' else -6.5
        elif leader in INSTITUTIONS and word in {'art', 'arts'}:
            value = -6.0
        elif word.isalpha() and subject_field(word):
            value = -3.5 if leader in INSTITUTIONS else 0.0
    elif leader == 'of' and prev + ' ' + word in REGIONS:
        formal = any(tail.lower().endswith(name + ' of ' + prev)
                     for name in INSTITUTIONS | {'city'})
        value = -4.5 if formal else -1.0
    if token == '$$' and tail.endswith('\n'):
        value = -1.1
    if word == 'affairs' and prev == 'veterans':
        value = -1.25
    if token == '-type' and previous == 'ref':
        value = -2.0
    if token.startswith('\n') and re.search(r'\n\n\n\d{1,3}$', tail):
        value = -2.0
    return (doc, token, previous, (tail + token)[-40:]), value

"""Recognize directional continuations after verbs, plus Cyrillic word endings.

English arrival/placement verbs give a large positive response on particles
such as 'up', 'forward' and 'forth'. Motion and delivery verbs give smaller
responses. Most other text is assigned zero. A second rule (below) estimates
negative responses on vowel-initial Cyrillic continuations inside words.
"""
from functools import lru_cache
import wordnet

READS = ()
PARTICLES = {'for', 'up', 'out', 'forward', 'forwards', 'forth', 'before', 'together'}
ARRIVAL = {'come', 'show', 'pop', 'appear', 'emerge', 'arise'}
DELIVERY = {'bring', 'throw', 'speak', 'draw', 'pull'}
MOTION = {'move', 'go', 'walk', 'run', 'roll', 'jump', 'spring', 'rush'}
POSITION = {'stand', 'lie', 'kneel', 'sit'}
VOWELS = set('аеёиоуыэюя')

@lru_cache(maxsize=8192)
def forms(word):
    return set(wordnet.base_forms(word)) | {word}

def direction(word, particle):
    f = forms(word)
    if particle == 'for':
        return 1.3 if 'provide' in f else 0.0
    arrival = bool(f & ARRIVAL)
    placed = 'put' in f
    strength = 0.1
    if arrival:
        strength = 3.8
    elif placed:
        strength = 4.2
    elif f & {'step', 'turn'}:
        strength = 4.4
    elif f & DELIVERY:
        strength = 2.1
    elif f & (MOTION | POSITION):
        strength = 1.5
    elif f & {'give', 'take', 'hold', 'keep', 'push', 'get'}:
        strength = 0.9
    if particle == 'up':
        return strength
    if particle == 'out':
        return 0.4 * strength
    if particle == 'together':
        return 0.7 * strength
    if particle == 'before':
        return 5.0 if arrival else (4.0 if f & POSITION else -0.18)
    if particle == 'forth':
        return 3.2 if 'set' in f else (1.5 * strength if placed else 0.0)
    if 'look' in f:
        return 0.5
    return (2.1 if arrival or placed else 2.8) * strength

# Common first roots in Russian compounds, before their connecting vowel о.
COMPOUND_STEMS = {
    'сам', 'благ', 'люб', 'жив', 'рук', 'перв', 'дост', 'лог',
    'закон', 'жертв', 'нефтегаз', 'против', 'труд', 'здрав',
    'прав', 'работ', 'вод', 'плод', 'род',
}

def continuation(stem, token):
    if token == 'яв' and stem in {'по', 'про'}:
        return 3.0  # появ-/прояв-: appearing or manifesting
    if not token or not stem or not ('а' <= token[0] <= 'я'):
        return 0.0
    if token.startswith('о'):
        if token in {'о', 'оп', 'ос', 'ор'} and stem in COMPOUND_STEMS:
            return -6.2 if token in {'оп', 'ос'} else -4.5
        if token == 'оп':
            return -4.0 if any(ch in VOWELS for ch in stem) else -1.5
        if stem.endswith('стр'):
            return 0.8  # стро-: building
        if token == 'о' and len(stem) > 2:
            return -3.2 if stem[-1] in 'бпвфм' else -0.6
        if token.startswith(('ор', 'ом', 'ос', 'оз', 'от', 'ож', 'оя')):
            return -0.5 if len(stem) > 2 else -0.1
        if token.startswith('ов') or token == 'ой':
            return -0.2
        return 0.0
    if token == 'ы':
        return -0.4
    if token in {'у', 'а', 'ами'} and len(stem) > 2:
        return -0.25
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = doc, '', ''
    _, word, previous = carry
    s = prefix.token_strings[-1].lower()
    name = s.strip().replace('-', '')
    value = continuation(word, s)
    boundary = not word or s[:1].isspace() or s.startswith('-')
    if boundary and name in PARTICLES:
        value = direction(word or previous, name)
    if boundary and name == 'tags' and (word or previous) == 'show':
        value = 2.6
    for ch in s:
        if ch.isalpha():
            word = (word + ch)[-40:]
        else:
            if word:
                previous = word
            word = ''
    return (doc, word, previous), value

"""Approximate a mixed lexical response, mostly negative.

Tell/treat spellings and their inflections are the main English triggers.
'Tell' is stronger near can/could or phrases about ability, possibility,
ease or difficulty; 'treatment of' also responds on 'of'.  Split spelling
pieces count too.  Short Han tokens containing 治 and the Korean syllable
치 form negative branches, as does Vietnamese trị (except giá trị,
'value').  Completing Greek την/στην is positive.

All other positions are zero.  This deliberately omits small background
fluctuations and many rare fragments.  History is local to each document.
"""
import re

READS = ()

# Regular inflections are separated because their response strengths differ.
VERB_RESPONSE = {
    'tell': -2.65,
    'tells': -1.4,
    'telling': -2.8,
    'told': -1.2,
    'treat': -1.7,
    'treated': -1.5,
    'treating': -1.75,
    'treats': -0.85,
    'treatment': -0.32,
    'treatments': -0.06,
}
ABILITY = re.compile(
    r"\b(?:can(?:not|['’]t)?|could(?:n['’]t)?)\b"
    r"((?:\s+\w+){0,5})\s*$",
    re.IGNORECASE,
)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        history = ''
    else:
        history = carry[1]
    token = prefix.token_strings[-1]
    word = token.lstrip(' .-_').lower()
    value = VERB_RESPONSE.get(word, 0.0)

    # A piece such as 'ell' after a token ending in 't' also spells 'tell'.
    if not value and token and token[0].isalpha():
        joined = (history[-1:] + token).lower()
        if joined in VERB_RESPONSE and history[-1:].lower() == 't':
            word = joined
            value = {'tell': -4.0, 'treat': -3.0, 'told': -2.5}.get(
                word, VERB_RESPONSE[word]
            )
            # The 'st' cluster is weaker (e.g. German stell- fragments).
            if history.lower().endswith('st'):
                value *= 0.25

    ability = ABILITY.search(history[-65:]) if word == 'tell' else None
    if ability:
        intervening = len(ability.group(1).split())
        value = -8.8 if intervening <= 1 else -6.0
        if re.search(r'\b(?:someone|anyone|somebody|anybody)\s*$', history):
            value = -6.0
        elif history.rstrip().lower().endswith('please'):
            value = -3.8
    if word == 'tell':
        if re.search(r'\b(?:possible|impossible|easy|difficult|hard)(?: way)? to\s*$',
                     history, re.IGNORECASE):
            value = -10.6
        elif re.search(r'\b(?:able|unable) to\s*$', history, re.IGNORECASE):
            value = -8.7
        elif re.search(r'\bhow (?:do|did) (?:you|we|they|i)\s*$',
                       history, re.IGNORECASE):
            value = -7.0
    previous = history.rstrip().split()[-1:]
    previous = previous[0].lower() if previous else ''
    if word == 'telling' and previous == 'of':
        value = -3.8
    if word == 'of' and previous == 'treatment':
        value = -1.1
    if token.strip() == 'Tell':
        value = -2.6
    elif token.strip() == 'Treat':
        value = -1.0
    if token == '-treated':
        value = -0.85

    # A smaller, positive branch: completion of Greek feminine articles.
    if token == 'ν':
        if re.search(r'(?:^|\W)τη$', history, re.IGNORECASE):
            value = 3.4
        elif re.search(r'(?:^|\W)στη$', history, re.IGNORECASE):
            value = 1.25
    if token == '치':
        value = -2.5
    if word == 'trị':
        value = 0.0 if previous == 'giá' else -4.8
    elif token == 'ị' and history.lower().endswith('tr'):
        value = -9.0

    if '治' in token:
        if token in ('治', '法治'):
            value = -8.3
        elif token == '治安':
            value = -5.8
        elif len(token) == 2:
            value = -1.3 if token == '政治' else -3.1
        else:
            value = -0.8

    return (document, (history + token)[-80:]), value

programs.haiku:
"""Layer 1, MLP down-projection, component 3666: a "treat / tell / cure" detector.

What it does: the component goes strongly negative on a few words for treating or telling,
and on the Chinese character 治 (cure, treat, govern). It is near zero everywhere else,
except for a steady positive value inside runs of middle dots (leader lines).

The main cases, as the program predicts them:
- "tell" in the sense "be able to tell" (after can / could / cannot / just): about -8.5.
  Other "tell": about -3. The forms tells / telling / told: -1.2 to -2.8.
- "treat" and its forms (treat, treated, treating): about -1.6. "treatment" is weak.
- 治 alone, or ending a word (法治 rule of law, 自治): about -8.
  Inside a longer medical or policy word (治疗, 治療, 治理): about -3.
  政治 (politics) only -1; 冶 and Korean 치 (cure) are treated like 治 / -3.
- A repeated middle dot after another middle dot (······): +1.7.

Everything else is predicted as 0.
"""

READS = ()

# "tell" after these words means "be able to tell": the strongest negative response.
ABILITY_BEFORE_TELL = {"can", "could", "cannot", "can't", "couldn't", "just", "possibly", "even"}
TELL_FORMS = {"tells": -1.4, "telling": -2.8, "told": -1.2}
TREAT_FORMS = {"treat": -1.7, "treats": -1.7, "treated": -1.5, "treating": -1.8, "treatment": -0.3}
DOT = "·"  # middle dot


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word == "tell":
        value = -8.5 if prev in ABILITY_BEFORE_TELL else -3.0
    elif word in TELL_FORMS:
        value = TELL_FORMS[word]
    elif word in TREAT_FORMS:
        value = TREAT_FORMS[word]
    elif word.endswith("政治"):
        value = -1.0
    elif word.endswith("治") or word == "冶":
        value = -8.0
    elif "治" in word or word == "치":
        value = -3.0
    elif word and set(word) == {DOT} and prev and set(prev) == {DOT}:
        value = 1.7
    else:
        value = 0.0
    return carry, float(value)

"""layers.1.mlp.down_proj:3668 -- a joiner word inside a compound or title.

The component fires on a short connecting word ("and", "of", "per", "the", "to", "&",
"de", "à") when it glues two parts of one compound term or title:
  slip-and-fall, state-of-the-art, pay-per-click, Tour de France, track & field,
  Court of Federal Claims, Steak 'n' Shake.
It responds most strongly to the hyphen-glued forms ("-and", "-of", "-the", "-per").
Space-separated connectors respond weakly, more after a capitalised word (a title or
name) than after a lowercase one. A Java "import" that starts a line responds, and the
first token of each document is slightly negative. Everything else is near zero.

step() predicts from the current token and the one before it; it has no state.
"""

READS = ()

GLUE_STRONG = {"and", "of", "the", "per", "as"}
GLUE_WEAK = {"to", "for", "by", "in", "de", "a", "it", "my", "your", "on", "at", "or"}
CONNECTORS = {"and", "of", "de", "à", "per", "by", "to", "the", "for", "in", "en", "it", "on", "as"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.25
    prev = prefix.token_strings[-2].strip()
    if tok.startswith("-") and word[1:].lower() in GLUE_STRONG:
        value = 3.0
    elif tok.startswith("-") and word[1:].lower() in GLUE_WEAK:
        value = 1.0
    elif word == "import" and "\n" in prefix.token_strings[-2]:
        value = 1.2
    elif word == "n" and prev[-1:] in ("'", "‘", "’"):
        value = 3.0
    elif tok.startswith(" ") and word == "&":
        value = 1.3 if prev[:1].isupper() else 0.35
    elif tok.startswith(" ") and word in CONNECTORS:
        if prev[:1].isupper():
            value = 0.35 if word in ("and", "of") else 0.2
        else:
            value = 0.12 if word == "and" else 0.0
    else:
        value = 0.0
    return None, value

programs.sol:
"""Responses at a few text boundaries, especially before dates.

Separate blanks after temporal/quantity prepositions are positive;
blanks after month names and at the start of lines are negative.
A colon after a document-initial 'Title' label has a much larger
response; lowercase and frontmatter title labels get smaller responses.
A coarse token-shape bias handles the first token of a document.
Other, mostly weak lexical activity is not modeled.
"""
import calendar
import regex

READS = ()
MONTHS = {s.casefold() for s in (*calendar.month_name, *calendar.month_abbr) if s}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, position, frontmatter = '', '', 0, False
    else:
        _, previous, tail, position, frontmatter = carry
    word = previous.strip().casefold()
    value = 0.0
    if position == 0:
        frontmatter = token.lstrip().startswith('---')
        text = token.strip()
        if token.isspace():
            value = 0.07
        elif text.isdigit():
            value = 0.12
        elif regex.search(r'\p{Script=Han}', text):
            value = -0.35
        else:
            value = -0.13
    elif token == ':' and word == 'title':
        if position == 1:
            value = 2.30 if previous == 'Title' else 0.27
        elif frontmatter and position < 8 and previous == 'title':
            value = 0.74
    elif token == ' ':
        if tail.endswith('\\n'):
            value = -0.52
        elif tail.endswith('\n'):
            value = -0.24
        elif word in {'in', 'at'}:
            value = 0.31
        elif word in {'since', 'until'}:
            value = 0.28
        elif word in {'from', 'around', 'about', 'on'}:
            value = 0.22
        elif word in {'before', 'after', 'during', 'of', 'for', 'with', 'between'}:
            value = 0.17
        elif word in {'by', 'to', 'than', 'over', 'under', 'into'}:
            value = 0.12
        elif word in MONTHS:
            value = -0.10
    state = (doc, token, (tail + token)[-4:], position + 1, frontmatter)
    return state, value

programs.haiku:
"""layers.1.mlp.down_proj:3670 -- a "number is coming" detector on the bare space token.

The tokenizer emits a bare " " token only in front of a number (digits are split one per
token), so this component mostly reads that space. Its value depends on the word before it:
- after a year cue (in, at, since, born, from, about, was, ...): clearly positive (~0.28),
  the model is about to write a year;
- after a mid-sentence word that often precedes a number (of, is, to, as, than, ...): mildly
  positive (~0.12); after ",", "and", "the": ~0.05;
- after a month name (the number is a day): slightly negative (~-0.10);
- after a line break or escaped newline ("\n", "n"): negative (-0.2 to -0.55);
- after "." or a lone space: ~-0.06.
At the first token of each packed row, with no context, it is a small offset by token kind:
digits +0.13, punctuation/symbols -0.27, other tokens -0.12.
Everything else is 0. This explains only a few percent of the variance: most of the
component's activation is diffuse, token-specific noise that no short rule captures.
"""
import unicodedata

READS = ()

MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December"}
YEAR_CUE = {"in", "In", "at", "since", "born", "around", "about", "from", "on",
            "between", "was", "over", "approximately"}
MID = {"of", "is", "to", "be", "are", "as", "than", "with", "for", "has", "de"}
ESCAPED_NEWLINE = {"n", "\\n"}


def value_after(word):
    if word in YEAR_CUE:
        return 0.28
    if word in MID:
        return 0.12
    if word in MONTHS:
        return -0.10
    if word in ESCAPED_NEWLINE:
        return -0.55
    if word in {"\n", "\t\n", ")\n", "\n\n", ":\n", " {\n", "\r"}:
        return -0.21
    if word in {",", "and", "the", "   "}:
        return 0.05
    if word in {".", " "}:
        return -0.06
    return 0.0


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if prefix.position == 0:
        if cur.isdigit():
            return None, 0.13
        if all(unicodedata.category(c)[0] in "PS" for c in cur):
            return None, -0.27
        return None, -0.12
    if cur == " ":
        return None, value_after(prefix.token_strings[-2])
    return None, 0.0

programs.sol:
"""Early-document indentation, fading with document length and line count.

A horizontal-whitespace token immediately after a newline is negative,
particularly near the start of a document. Repeated line breaks weaken
this response. Tabs strengthen it; a single space or an opening brace
at the preceding line's end weakens it. Other tokens predict zero.
The first token has separate, coarse whitespace-formatting baselines.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, lines, previous = 0, 0, ''
    else:
        _, position, lines, previous = carry
    text = prefix.token_strings[-1]
    horizontal = bool(text) and not text.strip(' \t')
    value = 0.0

    if position == 0:
        if horizontal:
            if '\t' in text:
                value = 0.065 if len(text) == 1 else 0.6
            else:
                value = -0.5 if len(text) == 1 else 1.0
        elif text and not text.strip('\r\n'):
            value = -0.59 if len(text) == 1 else -0.33
    elif horizontal and previous.endswith('\n'):
        strength = math.exp(-position / 128) / max(1, lines) ** 1.2
        response = -0.56
        if previous.rstrip().endswith('{'):
            response += 0.35
        if len(text) == 1:
            response += 0.11
        if '\t' in text:
            response -= 0.15
        value = 0.017 + strength * response

    return (doc, position + 1, lines + text.count('\n'), text), value

"""Approximate a Slavic word-onset feature, without a token-value table.

Transliterate the word prefix and respond at its first vowel-bearing token:
positive a-/da-/pa-/pra-, negative po-/do-/na-/za- and related onsets.
Cyrillic enables the rules directly. Latin text needs nearby Slavic function
words or diacritics. A comma strengthens the conjunction-like a response;
case, token splitting, script and additional vowels adjust the amplitude.
Separately read ne-/nie- negation prefixes allow another stem onset, and
Polish/Czech 'ale' ('but') has a positive response. Reset at document changes.
"""
import regex as re
from anyascii import anyascii

READS = ()

# Frequent grammatical words, not a list of memorized corpus tokens.
SLAVIC_WORDS = set('się jest nie przez oraz ale czy dla tego tym też już że '
                   'który są ze lub bude jsou když což které při však '
                   'také ještě byl jsem být není aby kde jeho sú koji '
                   'nije što će zašto'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0, '')
    _, old, slavic, previous = carry
    token = prefix.token_strings[-1]
    letters = token.lstrip()
    boundary = token != letters or not old or not token[:1].isalpha()
    if boundary:
        if old.lower() in SLAVIC_WORDS:
            slavic = min(4., slavic + 1.)
        old = ''
    slavic *= 0.995
    if re.search('[ąćęłńśźżčďěňřšťůžľĺŕ]', token.lower()):
        slavic = min(4., slavic + 1.5)
    match = re.match(r'[^\W\d_]+', letters, re.UNICODE)
    part = match.group() if match else ''
    # Only word beginnings matter; bound carry even for long identifiers.
    word = (old + part)[:48]
    cyrillic = bool(re.search(r'\p{Script=Cyrillic}', word))
    gate = 1. if cyrillic else min(1., slavic / 1.5)
    before, onset = anyascii(old).lower(), anyascii(word).lower()
    # A separately read ne-/nie- negation prefix can precede the stem.
    for negation in ('nie', 'ne'):
        if before.startswith(negation):
            before = before[len(negation):]
            onset = onset[len(negation):]
            break
    val = 0.
    if part and not re.search('[aeiouy]', before):
        syllable = re.match(r'[^aeiouy]*[aeiouy]', onset)
        if syllable:
            head = syllable.group()
            tail = onset[len(head):]
            split = bool(before)
            if head == 'a':
                if not tail:
                    if word.islower():
                        if cyrillic:
                            val = 7.0 if previous.rstrip().endswith(',') else 3.7
                        else:
                            val = 4.6 if previous.rstrip().endswith(',') else 1.7
                    else:
                        val = 2.6
                else:
                    val = 1.3 if cyrillic else 0.
            elif head in ('po', 'do', 'na', 'za'):
                if not tail:
                    val = {'po': -0.50, 'do': -0.05,
                           'na': -0.27, 'za': -0.39}[head]
                else:
                    strength = {'po': 2.3, 'do': 2.2,
                                'na': 1.9, 'za': 1.6}[head]
                    if cyrillic:
                        val = -strength * (2.1 if split else 1.)
                    else:
                        val = -1.6 * strength * (1.1 if split else 1.)
            elif head == 'o':
                if not tail:
                    val = -0.23
                elif tail.startswith('b'):
                    val = -1.5 if cyrillic else -2.2
                else:
                    val = -0.7 if cyrillic else -2.2
            elif head == 'u' and tail:
                val = -1.0 if cyrillic else -3.2
            elif head in ('pro', 'pri'):
                if not tail:
                    val = -0.25 if head == 'pro' else -0.47
                else:
                    val = (-3.1 if split else -0.9)
            elif head in ('pa', 'da', 'pra'):
                if not tail:
                    val = 2.4 if head == 'da' else 1.3
                elif split:
                    val = 1.7
                else:
                    val = 0.9 if head != 'pa' else 0.2
            # This is a short onset signal, not a whole-word topic feature.
            vowels = len(re.findall('[aeiouy]', onset))
            val *= (0.20 if cyrillic else 0.45) ** max(0, vowels - 1)
            # Polish and Czech 'ale' is the contrast conjunction 'but'.
            if onset == 'ale':
                val = 3.4 if word.islower() else 2.1
    if not part or len(part) != len(letters):
        word = ''
    return (doc, word, slavic, token), float(val * gate)

programs.haiku:
"""Component layers.1.mlp.down_proj:3672: a Russian word-opening detector.

What it does, in plain terms:
- Russian verb/preposition prefixes that open a word (по-, на-, за-, об-, под-, при-, от-, до-,
  про-, пре-, вы-, раз-, пере-) push the activation negative. The clearest cases are a prefix
  split across tokens, where the word is still only a prefix (e.g. 'н' + 'ав'-> 'нав', 'П' + 'ом'
  -> 'пом'): about -2.5. A prefix token that begins a word with a space gives a smaller
  negative: about -0.7 for 2-3 letters and -1.5 for 4.
- The Russian conjunction 'а' (but/and) is strongly positive, +7 right after a comma (", а"),
  +3 otherwise. A Latin-script 'a' is ignored.
- A few conjunctions/particles, 'да' and 'ale', are weakly positive (+2.5).

Everything else is 0. The program only reads the current word, from its first letter to the newest
token, so it is causal.
"""
READS = ()

PREFIXES = ("по", "на", "за", "об", "под", "при", "от", "до", "про", "пре", "вы", "раз", "пере")


def word_so_far(strings):
    """Lowercase letters of the current word, from its first token to the newest one."""
    out = ""
    for s in reversed(strings[-6:]):
        k = len(s) - 1
        while k >= 0 and s[k].isalpha():
            k -= 1
        out = s[k + 1:] + out
        if k >= 0:
            break
    return out.lower()


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    word = word_so_far(strings)
    if word == "а":
        after_comma = len(strings) > 1 and strings[-2].rstrip().endswith(",")
        return None, (7.0 if after_comma else 3.0)
    if word in ("да", "ale"):
        return None, 2.5
    if 2 <= len(word) <= 4 and word.startswith(PREFIXES):
        if not strings[-1].startswith(" "):
            return None, -2.5
        return None, (-0.7 if len(word) <= 3 else -1.5)
    return None, 0.0

programs.sol:
"""Numeric-field transitions, rather than the meaning of ordinary prose.

Predict small responses in ordinary text, and larger negative responses at
letter/digit boundaries in versions, paths and mixed identifiers. Strength
uses the length of the preceding digit run and the number of numeric chunks.
The format-specific adjustments distinguish versions, timestamps and hex IDs.
It also estimates file-like colons and a small document-start offset.
These are calibrated approximations; token-specific variation is omitted.
"""
import re

READS = ()
# Each triple is: offset, per preceding digit, per numeric chunk.
SUFFIX = {
    '-': (1.1, -0.28, -0.79),
    '.': (0.76, -0.57, -0.07),
    '/': (-0.44, -0.05, 0.05),
    '+': (0.01, 0.03, 0.02),
}
MARKER_SPLIT = (0.7, -0.34, -0.2)
NEW_NUMBER = (0.13, -0.05, -0.03)
AFTER_LETTER = (0.41, -0.29, -0.09)


def strength(weights, digits, chunks):
    a, b, c = weights
    return a + b * digits + c * chunks


def predict(text, token, previous, position):
    word = re.split(r'\s', text)[-1]
    value = 0.12 if position == 0 else 0.0
    if token in (':', '::') and re.search(r'\.[a-z]{1,5}$', word):
        value -= 0.55
    runs = list(re.finditer(r'[0-9]+', word))
    if not runs:
        return value
    last = runs[-1]
    gap = len(word) - last.end()
    n, g = min(len(last[0]), 6), min(len(runs), 4)
    letters = any(c.isalpha() for c in token)
    attached = bool(token) and not token[0].isspace()
    ending = gap == 0 and not token.isdigit()
    suffix = ending and attached and letters
    split = (0 < gap <= 3 and attached and letters
             and not any(c.isspace() for c in previous))
    new_number = token.isdigit() and 0 < gap <= 4
    if suffix:
        value += strength(SUFFIX.get(token[:1], (0, 0, 0)), n, g)
    if split and previous[:1] in ('-', '.', '/', '+'):
        value += strength(MARKER_SPLIT, n, g)
        if any(c.isalpha() for c in previous):
            value -= 0.35
    if new_number:
        after_letter = word[-1:].isalpha()
        value += strength(AFTER_LETTER if after_letter else NEW_NUMBER, n, g)
        letter_dash = bool(re.search(r'[A-Za-z]-$', word))
        if letter_dash:
            value -= 0.31
        if token == '0':
            if after_letter:
                value -= 0.58
            if letter_dash:
                value -= 0.98
