"""Rule-based sketch of layers.1.mlp.down_proj:3673's activation.

The component is near zero on almost every token. It is negative on a few
formulaic software strings, and positive on a run of middle dots:
  * a hyphen that follows a version-like chunk ("14.04.2-server", "v5.0.0-rc",
    "foo-1.2.5.dist-info") gives a weak negative value;
  * platform triples ("x86_64-linux-gnu") and Python install paths
    ("python3.10/site-packages") are strongly negative on their suffix;
  * the "::" between a pytest file and a test name is negative;
  * the "Final" of a Maven version ("3.8.16.Final") is strongly negative;
  * a leader of repeated middle dots ("··") is strongly positive.
"""

READS = ()


def _run(strs):
    """The whitespace-free text ending at the current token."""
    start = len(strs) - 1
    while start > 0 and not any(c.isspace() for c in strs[start - 1]):
        start -= 1
    return "".join(strs[start:])


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    cur = strs[-1]
    prev = strs[-2] if len(strs) > 1 else ""
    if len(cur) >= 2 and set(cur) <= set("·"):
        return None, 1.7
    if cur == "::" and prev.endswith(".py"):
        return None, -1.3
    if cur == "inal" and prev == ".F":
        return None, -4.0
    if cur == "-linux" and "x86_64" in _run(strs):
        return None, -6.0
    if cur in ("-packages", "/site") and "python" in prev:
        return None, -3.0
    if cur == "-packages" and prev == "/site":
        return None, -3.0
    if cur[:1] == "-" and prev[-1:].isdigit():
        return None, -0.2
    return None, 0.0

