"""Approximate a sparse character-family response, not an insect topic.

Single Han characters with the insect radical receive larger values when
their dictionary gloss contains an animal name. Multi-character tokens and
other meanings receive less. Unfinished insect-radical byte prefixes also
activate. Split U+E000--U+EFFF private-use glyphs receive stronger values
after long whitespace runs or recent Greek letters, as in extracted math.
UTF-8 state and these simple context cues reset at document boundaries.
Weak background activity and finer contextual variation are not modeled.
"""
from functools import lru_cache
import codecs
import unihan
import wordnet
import re
import unicodedata

