@lru_cache(maxsize=4096)
def names_animal(character):
    definition = unihan.definition(character) or ''
    return any(wordnet.is_a(word, 'animal')
               for word in re.findall(r'[a-z]+', definition.lower()))

@lru_cache(maxsize=65536)
def decode_piece(pending, token):
    decoder = codecs.getincrementaldecoder('utf-8')('replace')
    decoder.setstate((pending, 0))
    text = decoder.decode(token, final=False)
    return text.strip(), decoder.getstate()[0]

@lru_cache(maxsize=1024)
def insect_fraction(pending):
    """Fraction of possible completions having the insect radical."""
    if len(pending) != 2 or not 0xe0 <= pending[0] <= 0xef:
        return 0.0
    first = ord((pending + b'\x80').decode('utf-8'))
    return sum(unihan.radical(chr(first + i)) == 142
               for i in range(64)) / 64


@lru_cache(maxsize=65536)
def contains_greek(text):
    return any(c.isalpha() and unicodedata.name(c, '').startswith('GREEK')
               for c in text)

@lru_cache(maxsize=65536)
def contains_insect(text):
    return any(unihan.radical(c) == 142 for c in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
