    if tail == b'\xee':  # Start of a U+E000--U+EFFF private-use glyph.
        math_glyph = whitespace >= 8 or greek_age > 0
        value = 5.0 if math_glyph else 3.1
    elif pending == b'\xee' and tail.startswith(b'\xee'):
        value = 4.6 if math_glyph else 0.6
    elif pending.startswith(b'\xee'):
        value = 1.2 if math_glyph else 0.2
    elif insect_fraction(tail):
        value = 2.5 * insect_fraction(tail)
    elif len(text) == 1 and unihan.radical(text) == 142:
        if pending:
            value = 0.4
        elif text in '虫蟲':
            value = 1.5
        elif names_animal(text):
            value = 2.3
        else:
            value = 0.2
    elif contains_insect(text):
        value = 0.1
    elif tail and 0xe4 <= tail[0] <= 0xe9:
        value = 0.05
    elif pending and token and 0x80 <= token[0] <= 0xbf:
        value = 0.01
    whitespace = min(100, whitespace + len(token)) if token.isspace() else 0
    return (doc, tail, whitespace, math_glyph, greek_age), value

