    else:
        _, words, partial, initial, repeated = carry
        repeated = repeated and token == initial
    # Process word boundaries while retaining at most eight completed words.
    for char in token:
        if char.isalpha():
            partial += char
        elif partial:
            if len(partial) > 1:
                words = (words + [frequencies(partial.lower())])[-8:]
            partial = ''
    word = token.strip().lower()
