    if len(word) >= 3 and word.isalpha() and words:
        scores = [sum(w[k] for w in words) for k in range(len(LANGUAGES))]
        lang = max(range(len(scores)), key=scores.__getitem__)
        freq = frequencies(word)
        contrast = lang != 0 and freq[0] > 3 and freq[0] - freq[lang] > 1
