READS = ()
STOPS = set('.!?。！？…')
COMMAS = set(',，、')
CLAUSES = set(':;：；')
QUOTES = set('\"\'”’»」』')
TERMINALS = STOPS | COMMAS | CLAUSES


def pulse(left, right, across, suffix, age=None):
    if left not in TERMINALS:
        return 0.0
    stop = left in STOPS
    comma = left in COMMAS
    semi = left in ';；'
    if right == '\\':
        if suffix and not suffix.isspace() and suffix[0] != '$':
            return -0.2
        if across:
            return -1.4 if stop else -4.2
        return -0.4 if stop else (-1.5 if semi else -0.85)
    if right == '$':
        return -5.8 if across else (-4.3 if stop or comma else -0.5)
    if right in '*`':
