"""Approximate a short-word-beginning detector, not a token lookup table.

Compare how often a piece occurs as a whole word with how often longer words
start with it (from wordfreq's counted lexicons). A large gap suggests an
unfinished word. Short capitalized or consonant-heavy beginnings get the
largest values; pieces inside words and familiar whole words get little.
English completeness is also checked separately, so a piece that happens to
be a word in another language is not automatically treated as complete.
The numerical cutoffs and amplitudes are calibrated on training activations.
"""
import math
from functools import lru_cache
import regex
from wordfreq import get_frequency_dict, top_n_list

READS = ()
LATIN_LANGUAGES = ('en', 'de', 'fr', 'es', 'pt', 'it', 'nl', 'tr', 'id')


@lru_cache(maxsize=None)
def lexicon(language):
    frequencies = get_frequency_dict(language)
    beginnings = {}
    for word in top_n_list(language, 40000):
        if word.isalpha():
            frequency = frequencies.get(word, 0) * 1000
            for length in range(1, min(len(word), 9)):
                start = word[:length]
                beginnings[start] = beginnings.get(start, 0) + frequency
    return frequencies, beginnings


@lru_cache(maxsize=100000)
def word_properties(token):
    letters = ''.join(c for c in token.strip() if c.isalpha())
    lower = letters.lower()
    if regex.fullmatch(r'\p{Latin}+', letters):
        languages = LATIN_LANGUAGES
    elif regex.fullmatch(r'\p{Cyrillic}+', letters):
        languages = ('ru',)
    elif regex.fullmatch(r'\p{Greek}+', letters):
        languages = ('el',)
    elif regex.fullmatch(r'\p{Arabic}+', letters):
        languages = ('ar',)
    elif regex.search(r'\p{Han}', letters):
        languages = ('zh', 'ja')
    elif regex.search(r'[\p{Hiragana}\p{Katakana}]', letters):
        languages = ('ja',)
    elif regex.search(r'\p{Hangul}', letters):
        languages = ('ko',)
    elif regex.search(r'\p{Devanagari}', letters):
        languages = ('hi',)
    else:
        languages = ()

    whole = beginning = 0.0
    for language in languages:
        frequencies, beginnings = lexicon(language)
        whole = max(whole, 9 + math.log10(frequencies.get(lower, 1e-9)))
        beginning = max(beginning, 6 + math.log10(beginnings.get(lower, 0) + 1e-8))
    gap = max(-6, min(6, beginning - whole))
    vowel_fraction = sum(c in 'aeiouy' for c in lower) / max(1, len(letters))
    english, starts = lexicon('en')
    english_whole = max(0, 9 + math.log10(english.get(lower, 1e-9)))
    english_beginning = max(0, 6 + math.log10(starts.get(lower, 0) + 1e-8))
    english_gap = english_beginning - english_whole
    return (gap, english_whole, english_gap, beginning, len(letters), letters.istitle(),
            vowel_fraction, bool(regex.search(r'\p{Cyrillic}', token)),
            bool(regex.search(r'\p{Katakana}', token)))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    word_start = (token[:1].isspace() or
                  bool(token and not token[0].isalnum()) or
                  not previous.isalnum())
    carry = (document, token[-1:])
    (gap, english_whole, english_gap, beginning, length, title, vowels,
     cyrillic, katakana) = word_properties(token)
