        elif english_whole > 4.785:
            value = 0.449
        else:
            value = 1.056 if length <= 3 else 0.326
    elif not word_start:
        value = 0.667 if katakana else 0.043
    elif english_whole > 4.095:
        value = 0.659 if title else 0.304
    elif beginning <= 5.914:
