"""Enumeration openers.

The component fires on the words that open a new point in an expository list of
options, aspects or steps: a sentence that starts "One ..." or "Another ...", "Also",
"Alternatively", "Moreover"; "also" after a modal or auxiliary ("can also", "is also");
"the most" and the evaluative adjectives that follow it ("the most important", "a
common approach"); and "In addition". The strongest is "Another" at the start of a
sentence, then "One". The few words right after a sentence-opening "One" or "Another"
(the "such", "of", "way", "is" in "One such issue is ...") get a weaker boost.
Everything else is predicted as 0. Document boundaries reset the state.
"""

READS = ()

# Sentence-initial words that open the next point of a list.
OPENERS = {"Another": 4.0, "One": 2.5, "Also": 1.1, "Alternatively": 1.1, "Moreover": 1.0,
           "Furthermore": 1.0, "Additionally": 1.0, "First": 0.6, "Some": 0.6, "Other": 0.6}
# Auxiliaries and modals: mid-sentence "also" is strong after these ("can also", "is also").
AUX = {"is", "are", "can", "may", "could", "should", "will", "be", "was", "has", "have", "must",
       "might", "would"}
# Ranking and evaluative adjectives, comparatives and quantity words: "the most important".
RANK = {"most", "biggest", "best", "common", "important", "key", "main", "crucial", "relevant",
        "notable", "significant", "major", "primary", "greatest", "largest", "more", "less",
        "further", "additional"}
# Words that often open or continue a point: "another way", "one such", "example of".
FOLLOW = {"another", "addition", "several", "various", "other", "plus", "example", "instance",
          "approach", "way", "thing", "step", "possibility"}
SENT_END = {"", ".", "!", "?", ":", '"'}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    prev = "" if new_doc else prefix.token_strings[-2].strip()

    # carry: tokens since a sentence-opening "One" or "Another" (None once 3 tokens have passed)
    since = None if (carry is None or new_doc) else carry + 1
    if cur in ("One", "Another") and prev in SENT_END:
        since = 0
    if since is not None and since > 3:
        since = None

    if cur in OPENERS and prev in SENT_END:
        value = OPENERS[cur]
    elif cur == "also":
        value = 2.0 if prev in AUX else 0.5
    elif cur == "addition":
        value = 1.3
    elif cur == "most" and prev in {"the", "The"}:
        value = 1.5
    elif cur in RANK:
        value = 0.7
    elif cur in FOLLOW:
        value = 0.4
    else:
        value = 0.0
    if since in (1, 2, 3) and value < 1.0:
        value = 1.0 if since == 1 else 0.5
    return since, value

