"""An initial-token spelling feature, nearly silent after the first token.

Estimate the initial amplitude from case, preceding space, punctuation, and
English word frequency. Module-declaration words are less negative.
Repeating the same initial token keeps that amplitude;
a new token ends the initial run. Reset at packed-document boundaries.
This approximates the broad pattern, not the large word-specific extremes.
"""
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()

MODULE_DECLARATIONS = frozenset({
    'import', 'from', 'package', 'using', 'namespace',
    'module', 'export', 'require', 'include',
})

# Keys: (leading space, case). Values: intercept and frequency slopes.
# The last slope applies only above Zipf frequency 5.
# Frequency is centered at 3.
WORD_RULES = {
    (False, 'lower'): (-6.40, -0.87, 0.09),
    (False, 'title'): (-1.23, 0.23, -0.98),
    (False, 'upper'): (-2.27, -0.21, 0.43),
    (False, 'mixed'): (-1.08, 0.56, 0.00),
    (True, 'lower'): (-1.45, 0.10, -0.10),
    (True, 'title'): (-0.01, 0.40, -0.96),
    (True, 'upper'): (0.59, -0.13, 0.15),
    (True, 'mixed'): (0.37, 0.03, 0.00),
}

@lru_cache(maxsize=16384)
def initial_value(s):
    t = s.strip()
    spaced = s.startswith(' ')
    if not t:
        return 0.73 if '\n' in s else 0.68 if len(s) == 1 else -3.86
    if s.startswith('<|'):
        return 1.71
    if t.isascii() and t.isalpha():
        if not spaced and t in MODULE_DECLARATIONS:
            return -2.0
        case = ('lower' if t.islower() else 'title' if t.istitle()
                else 'upper' if t.isupper() else 'mixed')
        a, b, c = WORD_RULES[spaced, case]
        f = zipf_frequency(t, 'en')
        return a + b * (f - 3) + c * max(0, f - 5)
    if t.isdigit():
        return 0.66
    if regex.search(r'\p{Script=Han}', t):
        return 0.67
    if regex.search(r'\p{Script=Cyrillic}', t):
        return -0.57
    if regex.search(r'\p{Script=Arabic}', t):
        return 0.86
    if regex.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', t):
        return 0.68
    if any(c.isalpha() for c in t):
        return -0.13
    if '\n' in s:
        return 1.53
    if t[0] in ')]}':
        if len(t) == 1:
            return -1.87 if spaced else -8.69
        return 0.28 if spaced else -0.23
    if t[0] in '([{':
        return 1.63
    if t[0] in '.,;:!?':
        return 1.53
    if t[0] in '\'"`':
        return 0.87 if spaced else 0.54
    return 0.57


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(prefix.token_strings[-1])
        return (doc, token, value), value
    # Equal-token runs have the same content as their initial token.
    if token == carry[1]:
        return carry, carry[2]
    return (doc, None, 0.0), 0.0

