A separated minus is strongest after a relation or a word introducing a
negative value, or after a power. Other operands give weaker responses;
prose dashes and bullets give little. Separated plus signs are weaker still, while unspaced plus is usually
negative. Also recognize explicit for-loop membership and the digits 30/31.
These surface rules deliberately omit irregular word-specific responses.
"""
import re

READS = ()
RELATIONS = '=<>≈≃≤≥≠→'
UNARY_WORDS = {'is', 'are', 'was', 'were', 'be', 'return', 'or', 'and'}
LOOP = re.compile(
    r'(?:^|\n|\\n)[ \t]*(?:for|foreach)\s*(?:\(\s*)?'
    r'(?:(?:var|int|auto)\s+)?\w+(?:\s*,\s*\w+)*\s*$'
)
COMPREHENSION = re.compile(r'\[[^\]\n]{0,50}\bfor\s+\w+\s*$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
