        elif last and last in '([{':
            value = 0.61
        elif power:
            value = 0.92
        elif number:
            value = 0.14 if p in ('0', '1') else 0.30
        elif letter:
            value = 0.50 if math or not previous[:1].isspace() else 0.06
        elif last and last in ')]}':
            value = 0.32
        elif not p:
            value = 0.09
        elif math:
            value = 0.15
    elif token == ' +':
        if power:
            value = 0.66
        elif number:
            value = 0.05 if p in ('0', '1') else 0.25
        elif letter:
            value = 0.38 if not previous[:1].isspace() else (0.20 if math else 0.0)
        elif last and last in ')]}':
