        elif last and last in '([{':
            value = 0.27
    elif token.strip() in ('−', '±', '∓'):
        value = 0.24 if token[:1].isspace() or '−' in token else 0.67
    elif token.strip() in ('(-', '[-'):
        value = 0.21
    elif re.fullmatch(r'[=,{\]}][+-]', token.strip()):
        value = 0.38
    elif token in (')-', ')+', '-\\', '+\\'):
        value = 0.40 if '\\' in history[-80:] else 0.10
    elif token.strip() in ('+', '-') and '\n' in token:
        value = -0.26 if '+' in token else -0.12
    elif token.strip() == 'in' and (LOOP.search(history) or COMPREHENSION.search(history)):
