from wordfreq import zipf_frequency, get_frequency_dict

READS = ()
LANGUAGES = ('fr', 'it', 'es', 'pt', 'de', 'nl', 'sv', 'da', 'nb',
             'fi', 'pl', 'cs', 'sk', 'hu', 'ro', 'tr', 'id', 'el', 'ru')

@lru_cache(maxsize=60000)
def language_votes(word):
    english = zipf_frequency(word, 'en')
    return tuple(max(-4., min(4., zipf_frequency(word, lang) - english))
                 for lang in LANGUAGES)

def finish_word(scores, word):
    if len(word) > 1:
