# Short function words, grouped by their grammatical language.
PROFILES = {
 'fr': ((1.5, 'le les l'), (1.4, 'la'), (.8, 'en par qui'),
        (.5, 'pour sur vers au'), (.3, 'un une'), (-1.7, 'on')),
 'it': ((1.4, 'il la l con'), (1.15, 'le gli'), (1.7, 'per'),
        (.85, 'da che'), (1.15, 'i'), (.45, 'di un sul'), (.15, 'a'), (0., 'in')),
 'es': ((1.6, 'el'), (1.35, 'la los'), (1.2, 'las'), (.8, 'en por'),
        (1.1, 'con'), (.4, 'para'), (.25, 'un una'), (-.6, 'le')),
 'pt': ((2., 'o'), (1.4, 'os em'), (1., 'a as no com'),
        (.8, 'dos por'), (.5, 'e para da'), (.3, 'que'), (-.6, 'das')),
 'de': ((1.2, 'bei'), (.85, 'von'), (.4, 'mit'), (.2, 'die zum zur'), (0., 'in'), (.3, 'an')),
 'nl': ((1., 'van en'), (.4, 'met')),
 'sv': ((1., 'med till'), (.8, 'i på av'), (.5, 'en som och')),
 'da': ((1., 'med til'), (.8, 'i på og af'), (.4, 'en som'), (-1.3, 'for')),
 'nb': ((1., 'med til'), (.8, 'i på og av'), (.4, 'en som'), (-1.3, 'for')),
 'pl': ((.9, 'w z'), (.7, 'i o od'), (.4, 'dla na')),
 'cs': ((.8, 'od'), (.4, 'z o na')),
 'sk': ((.8, 'od'), (.4, 'z o na')),
 'hu': ((1.5, 'az'), (.85, 'a')),
 'ro': ((.7, 'la care'), (.4, 'pe'), (.2, 'să')),
 'id': ((.9, 'di'), (-.8, 'dan')),
 'tr': ((-.6, 've'),),
 'ru': ((.4, 'что'), (.15, 'с')),
