READS = ()

NAVIGATION = {
    'Home', 'Back', 'Close', 'Search', 'Login', 'Links', 'More',
    'Print', 'Subscribe', 'About', 'News', 'Filters', 'Menu',
    'Contact', 'Share', 'Posts', 'Blog', 'Popular', 'Latest', 'Articles',
}
HEADINGS = {'NAME', 'TITLE', 'JOIN', 'Abstract', 'Description'}
PAGE_LABELS = {
    'Category', 'Content', 'Catalog', 'Introduction', 'Navigation',
    'Examples', 'Other', 'Others', 'Related', 'RELATED', 'Changes',
    'Legend', 'Warning', 'Loading', 'Browse', 'Filter', 'Shop', 'Guest',
}
SITE_INTRO = {'Welcome', 'Explore', 'Learn', 'Download', 'View', 'Views'}


def opening(s):
    bare = s.lstrip()
    if bare.title() in NAVIGATION:
        if s.startswith(' '):
            return 0.0 if bare.islower() else -2.7
        return -4.7 if bare.islower() else -7.1
