        return -11.8
    if s in PAGE_LABELS:
        return -4.8
    if s in SITE_INTRO:
        return -3.0
    if s in {'Cart', 'Sale'}:
        return -9.8
    if s == 'with':
        return -17.8
    if s in {'or', 'WITH'}:
        return -11.8
    if s in {'and', 'by', 'to', 'in', 'With', 'By', 'OR'}:
        return -3.5
    if s.lower() == 'x':
        return -5.4 if s.islower() else -3.3
    if s.lower() == 'y':
        return -1.8
    if s in {'\\n', '\\t', '\\r'}:
        return -6.7
    if '\xa0' in s and s.isspace():
        return -5.8
    if s == '<?':
        return -5.5
    if s.startswith('/*') and not s.endswith('\n'):
        return -5.5 if s.count('*') > 2 else -3.0
    if s == '<!--':
        return -3.8
