    if text == '<|endoftext|>':
        return -2.94
    if text.startswith('<|'):
        return -0.19
    if text == '//\n':  # An empty C/C++-style line comment.
        return -4.54
    if len(text) >= 2 and set(text) == {'·'}:
        return -2.81
