        if word.isupper():
            return -0.38
        if text[0].isspace():
            return -0.61
        if word.istitle():
            return -0.51
        return -0.73 if word.islower() else -0.42
    return -0.62 if any(c.isalnum() for c in word) else -0.22


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
