LANGUAGE_BE = {
    'est': ('fr', 2.95), 'ist': ('de', 2.45),
    'war': ('de', 2.30), 'es': ('es fr', 2.15),
    'son': ('es', 2.90), 'é': ('pt', 2.80),
    'je': ('cs sk sh sl', 3.20), 'er': ('da nb', 2.90),
    'era': ('es it pt', 1.95), 'sea': ('es', 2.05),
    'este': ('ro', 4.20), 'jest': ('pl', 2.05),
}
STRONG_COPULAS = set('sind sont são waren était étaient sunt'.split())
OTHER_COPULAS = {
    'è': 2.70, 'sono': 1.95, 'suis': 1.80, 'êtes': 1.70,
    'sei': 1.25, 'zijn': 1.85, 'ser': 0.70, 'être': 1.45,
    'été': 1.55, 'essere': 1.25, 'sido': 1.98,
    'быть': 0.95, 'был': 0.78, 'ole': 0.65,
    'là': 0.53, 'adalah': 0.83,
}
CHANGE_OF_STATE = {
    'become': 0.63, 'became': 0.54,
    'becomes': 0.31, 'becoming': 0.47,
}


def language_response(context, languages, response):
    """Compare recent words' corpus frequencies, not the current spelling."""
    words = re.findall(r"[^\W\d_]+", context.lower())[-8:]
    if not words:
        return response * 0.5
    weights = [0.8 ** (len(words) - i - 1) for i in range(len(words))]

    def score(language):
        return sum(w * zipf_frequency(s, language)
                   for w, s in zip(weights, words)) / sum(weights)

    own = languages.split()
    alternatives = set('en fr de es pt it nl'.split()) - set(own)
    difference = max(map(score, own)) - max(map(score, alternatives))
