"""Closing-bracket detector with a short-span condition: a closing bracket
(')', ']', '}', '>') that closes a bracket opened within the last 8 tokens
predicts a small positive activation; square brackets a bit more than the others."""

READS = ()

OPENERS = {"(": ")", "[": "]", "{": "}", "<": ">"}
CLOSERS = {")": "(", "]": "[", "}": "{", ">": "<"}
WEIGHT = {"]": 0.3, ")": 0.2, "}": 0.1, ">": 0.1}
SPAN = 8


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok not in WEIGHT:
        return carry, 0.0
    recent = prefix.token_strings[-SPAN - 1:-1]
    opener = CLOSERS[tok]
    if any(opener in s for s in recent):
        return carry, WEIGHT[tok]
    return carry, 0.0

