            return 3.47
        if p == 'ahead' and b in {'look', 'looking', 'looks', 'looked'}:
            return 1.2
        if p in {'wait', 'waiting', 'waited'}:
            return 1.15
        if p == 'excited':
            return 0.95
        if p in {'happy', 'pleased', 'delighted', 'thrilled'}:
            return 0.46
        if p == 'committed':
            return 0.7
        if p in {'dedicated', 'devoted', 'commitment'}:
            return 0.23
        if p == 'ready':
            return 0.3
        if p in {'eager', 'willing', 'prepared', 'glad', 'proud'}:
            return 0.15
        if p in {'close', 'open'}:
            return 0.4
        if p == 'here':
            return 0.5
        if p == 'available':
            return 0.12
        if p in {'listen', 'listening', 'listened', 'subscribe', 'refer', 'referred',
                 'referring', 'belong', 'belongs', 'belonging'}:
            return 0.21
        if p == 'writing':
            return 0.13
    # Explanations and invitations to continue reading.
    if c == 'of':
        if p in {'equation', 'formula'}:
            return 0.4
        if p == 'example':
            return 0.33
        if p == 'examples':
            return 0.16
    if c == 'more':
        if p == 'see':
            return 1.05 if previous.strip() == 'See' else 0.44
        if p in {'read', 'write', 'provide', 'view', 'learn', 'know'}:
            return 0.3
    if p in {'waiting', 'wait', 'waited'}:
        if c == 'on':
            return 0.66
        if c == 'for':
            return 0.3
    if c == 'on' and p == 'working':
        return 0.45
    if c == 'do' and p == 'how':
        return -0.52
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
