    return tuple(min(5.0, zipf_frequency(word, lang)) for lang in LANGUAGES)


def language(text):
    words = re.findall(r'[^\W\d_]{2,}', text.lower())[-12:]
    if not words:
        return 'en'
    scores = [0.0] * len(LANGUAGES)
    for word in words:
