        else:
            value = 1.8
    elif tok == " \\\\":
        value = 3.4 if in_string else -3.7
    elif tok == " ":
        if recent.endswith("\\n"):
            value = 1.5
        elif recent.endswith("\n"):
            value = 0.9
    elif tok == "··":
        value = -3.2
    recent = (recent + tok)[-200:]
    return (doc, pos + 1, recent, tok), value

programs.sol:
"""Number prefixes and structural punctuation, mostly silent elsewhere.

Negative responses mark the digit completing an initial 19/20 number prefix,
especially after date words, months, and citation markers. Many numeric
separators and mathematical contexts weaken this response. Positive responses mark indentation not recently repeated,
and key/value colons. Initial articles, prepositions and possessive forms
have negative class baselines. Initial "12" and "Title:" have explicit
exceptions. These are surface heuristics, not a full date parser.
"""
import calendar
import math
import re
import regex

READS = ()
MONTHS = {m.lower() for m in calendar.month_name if m}
TIME_WORDS = set('in during since before after until late early mid from'.split())
DATE_WORDS = set('born copyright year dated published updated revised'.split())
POSSESSIVES = set('my your his her its our their mine yours hers ours theirs'.split())
ARTICLES = {'a', 'an', 'the'}
PREPOSITIONS = set('of to by in on at from for with about as'.split())
CITATION = re.compile(
    r'\bet\s+al[.,]*\s*$|\\cite\w*(?:\[[^]]*\])?\{[^}]*$')
QUANTITATIVE = re.compile(
    r'[=+*]|\d[.,/]\d|\\(?:frac|sqrt|sum)\b'
    r'|\b(?:kg|cm|mm|percent|approximately)\b')
COPYRIGHT_NOTICE = re.compile(
    r'(?:copyright|©|\(c\))[^0-9\n]{0,60}$', re.I)



def century_value(before, number):
    # A century-like prefix inside a hex literal or thousands group is not a year.
    if re.search(r'0x[0-9a-fA-F]*$', before):
        return 0.0
    if re.search(r'\d,$', before):
        return 0.4
    value = -1.02 - 0.26 * (number == '19')
    last = before[-1:]
    match = re.search(r'([A-Za-z]+)[.,–-]*\s*$', before)
    word = match[1].lower() if match else ''
    copyright_notice = bool(COPYRIGHT_NOTICE.search(before))
    if before.endswith('\n'):
        value += 0.24
    if before.endswith(('  ', '\t')):
        value += 0.77
    if last == '\xa0':
        value += 0.56
    if last == '(':
        value -= 0.43
    elif last in ('.', ',', '-', '–', '_', ':', "'"):
        if not (last in ('-', '–') and word in TIME_WORDS):
            value += 0.5
    elif last in ('=', '+', '*', '<', '>', '$', '%'):
        value += 0.7
    elif last in ('[', '{'):
        value += 0.44
    elif last.isascii() and last.isalpha():
        value += 0.3
    elif regex.search(r'\p{Script=Han}$|[，。：]$', before):
        value -= 0.55
    if word in TIME_WORDS:
        value -= 0.75
    elif word in ('born', 'year') or copyright_notice:
        value -= 1.0
    elif word in MONTHS or word in DATE_WORDS:
        value -= 0.6
    elif word in ('the', 'a', 'an'):
        value -= 0.54
    elif word in ('of', 'to', 'and', 'or'):
        value += 0.18
    if re.search(r'\b\d+\s+$', before):
        value += 0.6
    if CITATION.search(before):
        value -= 1.2
    elif not copyright_notice and QUANTITATIVE.search(before[-60:]):
        value += 0.4
    return max(-3.0, min(0.1, value))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, {}, {})
    _, history, position, indents, key_counts = carry
    token = prefix.token_strings[-1]
    value = -0.003
    if position == 0:
        word = token.strip().lower()
        if word in POSSESSIVES:
            value = -1.1
        elif word in ARTICLES:
            value = -0.42
        elif word in PREPOSITIONS:
            value = -0.3
    if len(token) == 1 and token in '0123456789':
        digits = re.search(r'[0-9]*$', history)[0]
        number = digits + token
        if number in ('19', '20'):
            value = century_value(history[:-1], number)
            if position == 1:
                value = -0.47 if number == '20' else -0.79
        elif number == '12' and position == 1:
            value = -3.33
        elif number.endswith('20'):
            value = 0.55 if len(number) == 3 else 0.35
        elif number.endswith('19') and len(number) == 3:
            value = 0.2
        elif number == '30':
            value = -0.39
        elif number == '31':
            value = -0.29
    elif len(token) > 1 and token == ' ' * len(token):
        value = -0.03
        if history.endswith('\n') or not history:
            width = len(token)
            masses = {w: c * math.exp(-(position - p) / 50.0)
                      for w, (p, c) in indents.items()}
            same = masses.get(width, 0.0)
            novelty = 1.0 / (1.0 + sum(masses.values()) + same)
            # The following token often contains the last space of a code indent.
            regular_code_indent = width % 4 == 3
            scale = 1.15 + 0.1 * (width % 4 == 0)
            scale -= 0.25 * regular_code_indent
            last = history.rstrip()[-1:]
            scale -= 0.3 * (last == '{')
            scale -= 0.17 * (regular_code_indent and last in ('{', '(', ':'))
            if history:
                value = -0.13 + scale * novelty
            indents[width] = (position, same + 1.0)
    elif token == '\":':
        key = re.search(r'([A-Za-z_]+)$', history)
        key = key[1] if key else ''
        count = key_counts.get(key, 0)
        value = (0.98 if key == 'name' else 0.60) / (1 + 0.15 * count)
        if re.search(r'":\d|":\{', history[-60:]):
            value *= 0.4
        key_counts[key] = count + 1
    elif token == ':':
        line = history.rsplit('\n', 1)[-1]
        identifier = re.search(r'[A-Za-z_]\w*$', line)
        if identifier:
            code = bool(re.search(r'\b(def|fn|let|const|var)\b', line))
            label = bool(re.fullmatch(r'\s*\w+', line))
            value = -0.08 + 0.37 * ('{' in history)
            value += 0.1 * ('{' in line) + 0.1 * code
            value += 0.12 * bool(line[:1].isspace()) + 0.15 * label
            value += 0.06 * bool(re.search(r'\s\w+$', line))
            value = max(0.0, value)
            if position == 1 and history == 'Title':
                value = 3.25
        else:
            value = 0.0
    history = (history + token)[-400:]
    return (doc, history, position + 1, indents, key_counts), value

programs.haiku:
"""Year-digit detector with a small positive side (v5).

Main effect: the second digit of a four-digit year written in prose ("in 19|62",
"the 20|14", "July 19|95") is strongly negative. Years starting 19 are strongest, 20 a bit
weaker; time words before the year (in, the, since, months) make it stronger. The second
digit of other numbers (e.g. after "=" or in code) is scaled down to a tenth.
Smaller effects: a colon after a word or a quoted key colon is mildly positive, and so is
4 or 8 spaces of indentation at the start of a line.
"""
READS = ()

DIGITS = "0123456789"
TIME_WORDS = {"in", "the", "of", "from", "since", "until", "by", "during", "around",
              "circa", "early", "late", "mid", "on", "for", "to"}
MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December"}


def year_value(first, second, word):
    """Activation of the second digit of a year that starts with `first`+`second`."""
    if first + second == "19":
        return -1.9 if word in TIME_WORDS or word in MONTHS else -1.2
    if first + second == "20":
        return -1.5 if word in TIME_WORDS or word in MONTHS else -0.9
    return 0.0


def is_prose_before(word):
    w = word.strip()
    return w != "" and (w.isalpha() or w in (",", "(", ".", ";", '"', "“"))


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = s[-1]
    value = 0.0
    if len(s) >= 2 and s[-1] in DIGITS and s[-2] in DIGITS:
        if len(s) < 3 or s[-3] not in DIGITS:
            word = s[-4].strip() if len(s) >= 4 and s[-3] == " " else ""
            value = year_value(s[-2], s[-1], word)
            if len(s) >= 4 and s[-3] == " " and not is_prose_before(s[-4]):
                value *= 0.1
    elif t == '":':
        value = 0.6
    elif t == ":" and len(s) >= 2 and s[-2][-1:].isalnum():
        value = 0.1
    elif t in ("    ", "        ") and len(s) >= 2 and "\n" in s[-2]:
        value = 0.3
    return carry, float(value)

programs.sol:
"""A negative detector for the jing/經 family of written syllables.

The largest responses are to 經, its simplified Chinese and Japanese forms,
Latin jing, and Korean 경.  Whole words containing those syllables have a
weaker response.  A two-byte tail recovers Han characters split by the
byte tokenizer; the remaining short tail recognizes split romanizations.
A small positive default applies only at document starts.  Common compounds
receive reduced weights; this is a spelling-family approximation, not a
general economic-topic rule.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    beginning = carry is None or carry[0] != doc
    if beginning:
        previous_bytes, previous_text = b'', ''
    else:
        _, previous_bytes, previous_text = carry
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', errors='ignore').strip()
    text = (previous_bytes + raw).decode('utf-8', errors='ignore')
    joined = previous_text + raw.decode('utf-8', errors='ignore')
    value = 0.22 if beginning else 0.0

    if any(c in text for c in '经經経'):
        if token in ('经', '經', '経') or not token:
            value = -11.2
            if previous_text.endswith(('曾', '已')):
                value = -2.2  # once/already, split across tokens
            elif previous_text.endswith(('诗', '詩', '正')):
                value = -7.0  # established compounds: 诗经 and 正经
        elif token in ('经过', '經過', '一经', '一經'):
            value = -5.5
        else:
            # Longer merged tokens dilute the single-character feature.
            value = -2.5 if len(token) == 2 else -0.6
            if token.endswith(('经理', '經理')):
                value = -0.2  # manager titles are a weak exception
    elif raw == '経'.encode('utf-8')[:2]:  # its first two bytes
        value = -1.9
    elif '京' in text:
        value = -4.0 if token == '京' or not token else -1.5
        if token == '北京时间':
            value = -2.5
    elif '경' in text:
        value = -4.8 if token == '경' or not token else -1.5
        if previous_text.endswith('환'):
            value = -0.8  # 환경, environment
    elif token in ('过', '過') and previous_text.endswith(('经', '經')):
        value = -5.0  # 经过, to pass through
    elif token in ('径', '徑'):
        value = -3.3
    elif token == '精':
        value = -1.4
    elif 'jing' in token.lower():
        value = -7.0 if token.lower() == 'jing' else -2.5
    elif token.lower() in ('ing', 'inh'):
        word = re.search(r'[A-Za-z]+$', joined)
        word = word.group().lower() if word else ''
        if word == 'kinh':
            value = -12.0
        elif word.endswith('jing'):
            value = -3.0
        elif word == 'king':
            value = -3.0
        elif word == 'ching':
            value = -1.8
    elif token.lower() == 'king':
        value = -0.65

    # Neither history buffer can grow with the document.
    return (doc, raw[-2:], joined[-12:]), value

programs.haiku:
"""Layer-1 MLP down-projection component 3706, as a readable rule.

What it responds to: line layout. The component fires on the token that ends a sentence
(". ! ? 。" and variants such as '."' or ")."), on a line break, and on indentation at the
start of a line. Everything else predicts 0. The sign follows how long the current line
has run, measured in tokens since the last line break:

- Sentence end or line break after a short line (under about 30 tokens: chat turns, list
  items, code, short sentences): near zero to mildly positive, up to +0.2.
- Sentence end or line break after a long line: negative, falling to about -0.9 by 160
  tokens. Long unbroken runs of prose (encyclopedic text, patent-style paragraphs) are
  the strongly negative case. A "!" adds +0.4 (exclamations are positive).
- Indentation at the start of a line follows the line before it. After a line that opens
  a block (ends in "{", ":" or "("), it is +0.9. After a long prose line that ended in a
  period, it is -1.1 to -1.8. After any other long line, -0.4. Otherwise +0.1.

The main program is `step`: it keeps a small carry (tokens in the current line, length
and ending of the previous line) and resets it at each document boundary.
"""

READS = ()

SENTENCE_END = set(".!?。！？")
CLOSERS = ")]\"'”’」）"
OPENERS = set("{:(")

# (tokens since the line break, activation), linearly interpolated between points.
LINE_CURVE = [
    (0, 0.05), (10, 0.2), (20, 0.15), (30, 0.0),
    (40, -0.35), (80, -0.6), (160, -0.9), (300, -1.0),
]


def _curve(n):
    if n <= LINE_CURVE[0][0]:
        return LINE_CURVE[0][1]
    for (x0, y0), (x1, y1) in zip(LINE_CURVE, LINE_CURVE[1:]):
        if n <= x1:
            return y0 + (y1 - y0) * (n - x0) / (x1 - x0)
    return LINE_CURVE[-1][1]


def _is_sentence_end(tok):
    core = tok.strip().rstrip(CLOSERS)
    return core[-1:] in SENTENCE_END


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        cur, prev_len, prev_end, line_end = 0, 0, "", ""
    else:
        _, cur, prev_len, prev_end, line_end = carry
    value = 0.0
    if tok.strip() == "" and cur == 0 and "\n" not in tok:
        # indentation at the start of a line, judged by the line before it
        if prev_end in OPENERS:
            value = 0.9
        elif prev_end == "." and prev_len > 30:
            value = -1.8 if prev_len > 80 else -1.1
        elif prev_len > 80:
            value = -0.4
        else:
            value = 0.1
    elif _is_sentence_end(tok):
        value = _curve(cur)
        if "!" in tok or "！" in tok:
            value += 0.4
    elif "\n" in tok:
        # a line break that closes a long line is negative, like a sentence end
        value = min(0.0, _curve(cur))
    if tok.strip():
        line_end = tok.strip()[-1:]
    if "\n" in tok:
        prev_len, prev_end, cur, line_end = cur + 1, line_end, 0, ""
    else:
        cur += 1
    return (doc, cur, prev_len, prev_end, line_end), value

programs.sol:
"""Approximate the component's negative response to S-L clusters.

Match transliterated spellings within a token or across its two predecessors.
Short tokens and a newly arriving L after S are strongest; long tokens are
weaker. Inflected 'slip' and the 'slav/slaw' spelling get separate strengths.
Syllabic East Asian spellings allow vowels after S and Japanese R/L equivalence.
Unmatched activity is zero; lexical and contextual residuals are not modeled.
"""
import re
from functools import lru_cache
import regex
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def spelling(raw):
    east = bool(regex.search(r'[\p{Han}\p{Katakana}\p{Hangul}]', raw))
    s = anyascii(raw).lower()
    if east:
        s = re.sub(r's[aeiou]+l', 'sl', s)
        if regex.search(r'\p{Katakana}', raw):
            s = re.sub(r'^r', 'l', s)
    # Keep emphatic Arabic S distinct from the ordinary S-L spelling.
    if 'ص' in raw:
        s = s.replace('sl', 'xl')
    return s, east


def response(older, previous, raw):
    s, _ = spelling(raw)
    p, syllabic = spelling(previous)
    context, _ = spelling(older + previous)
    t = s.strip()
    n = len(t)
    cluster = re.search('sl', t)
    if cluster:
        if n <= 3:
            return -1.7 if raw[:1].isspace() else -3.5
        if re.fullmatch(r'slip(?:s|ped|ping)?', t):
            return -4.7
        if 0 < cluster.start() <= 2 and raw.strip()[:1].isupper():
            return -1.1
        return -0.6 if n <= 5 else -0.15
    if raw[:1].isspace():
        return 0.0

    prior = re.sub(r'[aeiou]+$', '', context) if syllabic else context
    # Chinese 'shi', for example, is SH rather than the S sought here.
    end_s = (prior.endswith('s') if syllabic else
             bool(re.search(r'(s|sch|sh)\Z', prior)))
    if end_s and t.startswith('l'):
        if t.startswith(('lav', 'law')):
            value = -9.5
        else:
            value = -5.0 if n == 1 else (-3.0 if n <= 3 else -0.6)
        if not syllabic and prior.endswith(('sch', 'sh')):
            value *= 0.6
        if len(p.strip()) > 4:
            value *= 0.5
        elif p.strip() == 's':
            value *= 0.75
        return value
    if end_s and 'l' in t[:3]:
        return -0.1
    if re.search(r'sl[aeiou]?\Z', context) and t[:1].isalpha():
        if t.startswith(('av', 'aw')):
            return -4.7
        return -2.6 if n == 1 else -1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        older, previous = '', ''
    else:
        older, previous = carry[1:]
    raw = prefix.token_strings[-1]
    return (doc, previous, raw), response(older, previous, raw)

"""A sparse recognizer for source-code idioms, not a general code parser.

The large responses are in counting-loop headers, C includes, and Java or
React imports. Smaller responses mark URLs and Go/PHP syntax. Most other
text is assigned zero. A short suffix recognizes unfinished headers; document
boundaries reset it. Initial imports/includes receive an extra boost.
"""
import re

READS = ()
TYPES = {'int', 'long', 'var', 'let', 'size_t', 'unsigned', 'auto'}
ITERATORS = {
    'key', 'value', 'line', 'row', 'column', 'index', 'idx',
    'item', 'file', 'filename', 'name', 'attr', '_', '_,'}
LOOP = re.compile(r'.*\b(for|while)\b\s*(.*)$')
INTRO = re.compile(
    r'\bfor\s*\(?\s*(?:(?:int|long|var|let|size_t|unsigned|auto)\b\s*)?$')
DECL = re.compile(r'\b(?:int|long|var|let|size_t)\s*$')
ANGLE = re.compile(r'<(?:=|[A-Za-z_][A-Za-z_0-9]*|\()?')


def predict(token, previous, before, position):
    s, p = token.strip(), previous.strip()
    # Code is sometimes quoted with escaped newlines or inline-code markup.
    b = before.replace('\\n', '\n').replace('\\t', '\t').replace('`', '')
    b = b.replace('\u00a0', ' ')
    early = position < 4
    value = 0.1 if position == 0 else 0.0

    if s == '://':
        value += 1.31
    if s == '.com' and p.endswith('github'):
        value += 1.99
    if p == 'import':
        if s == 'java':
            value += 9.73 + 8.70 * early
        elif s == 'React':
            value += 13.08 + 6.61 * early
        elif s in {'javax', 'android', 'org', 'com', 'static'}:
            value += 1.62
    if p == 'package' and s in {'com', 'org'}:
        value += 1.61
    angle = bool(ANGLE.fullmatch(s))
    if p in {'#include', 'include'} and angle:
        value += 10.68 + 4.16 * early
        if s == '<stdio':
            value -= 4.04
        elif s not in {'<', '<iostream'}:
            value -= 9.27
    if p == '<' and s in {'stdio', 'iostream'}:
        value += (7.39 if s == 'stdio' else 12.48) + 3.82 * early
    if s == '"fmt' and re.search(r'\bimport\s*\([^)]*$', b):
        value += 3.65
    if s == '=>' and re.search(r'\bforeach\s*\([^{}]*$', b):
        value += 6.13

    # Recognize C-family parenthesized headers and Go's "for i := ...".
    m = LOOP.match(b.rsplit('\n', 1)[-1])
    clause = m.group(2) if m else ''
    depth = clause.count('(') - clause.count(')')
    for_header = bool(m) and m.group(1) == 'for'
    for_header = for_header and not any(c in clause for c in '{}')
    for_header = for_header and (
        depth > 0 if clause.startswith('(') else
        depth >= 0 and bool(re.match(r'[A-Za-z_]\w*\s*:=', clause)))
    semis = clause.count(';') if for_header else 0
    simple_while = bool(m) and m.group(1) == 'while' and bool(
        re.fullmatch(r'\(*\s*[A-Za-z_]\w*\s*', clause))
    identifier = bool(re.fullmatch(r'[A-Za-z_]\w*,?', s)) and s not in TYPES
    iterator = s in ITERATORS or (
        len(s) == 1 and s.isascii() and s.islower() and s != 'a')
    intro = bool(INTRO.search(b))
    if intro:
        if identifier and iterator:
            value += 0.73 + 0.87 * bool(DECL.search(b))
        value += {'i': 5.07, 'j': 2.72, 'key': 3.29}.get(s, 0.0)
        if s in {'_', '_,'}:
            value += 7.52
    elif DECL.search(b) and s == 'i':
        value += 1.44

    if for_header:
        if s == ';':
            value += 2.17
        if re.fullmatch(r';[A-Za-z_]\w*', s):
            value += 5.87
        if identifier and b.rstrip().endswith(';'):
            if semis == 1:
                value += 0.82 + 2.64 * (len(s) == 1)
                value += {'i': 4.77, 'j': 2.42}.get(s, 0.0)
            elif semis >= 2:
                value += 2.31 + {'i': 4.37, 'j': 2.64}.get(s, 0.0)
        if semis >= 2 or s.startswith(';'):
            if '++' in s or '--' in s:
                value += 8.11 - 4.13 * (')' in s)
                if b.rstrip().endswith(','):
                    value -= 6.0
        if semis >= 2 and identifier and p in {'++', ';++', '--'}:
            value += 1.99 + 5.96 * (s == 'i')

    # A comparison fused with its bound (e.g. '<n') responds less strongly.
    if angle and (semis == 1 or simple_while):
        value += 14.60 - 4.62 * simple_while
        if s == '<=':
            value -= 4.98
        elif len(s) > 1:
            value -= 5.18
    elif angle and not for_header and p in {'i', ';i'}:
        value += 2.57
    if s == '!=':
        value += 0.70
        if (semis == 1 or simple_while) and p.isidentifier():
            value += 4.22
    go_condition = bool(re.search(r'\bif\s+[^\n{}]*;[^\n{}]*$', b))
    if go_condition:
        if p.endswith(';'):
            value += {'err': 7.09, 'ok': 2.33}.get(s, 0.0)
        if s == '!=':
            value += 5.85
    elif s == '!=' and p == 'err':
        value += 1.79
    if p == 'if' and s == 'err':
        value += 1.61
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, previous, position = '', '', 0
    else:
        _, before, previous, position = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, before, position)
    return (doc, (before + token)[-240:], token, position + 1), value

programs.haiku:
"""Code-idiom detector: fires on the token that completes a predictable piece of
source code, mostly the comparison and loop variable of a C-style loop header.

The component is a sparse, signed feature: about 0 almost everywhere, large on a few
tokens of code. Its activation by case (typical value):
- `<` in `#include <...>`: 11.
- the library root right after `import`: `java` 9, `React` 12, `javax` 6,
  `com` / `org` 1.5.
- `.com` right after `github`: 2.
- `://` right after `http` or `https`: 1.25.
- `!=` right after `err` (Go's `if err != nil`): 6.
- inside a `for (...)` header, after a `;`: `<`, `<=`, `!=` (also merged with the next
  word, like `<n`) comparing the loop variable with its bound: 14; `>` 6.
- inside a `for (...)` header, before any `;`: `<`, `<=`, `!=` 6; the loop variable
  `i` 6 (2 when unspaced), `j` 3, `x` 2; `;` 1; the step `++`, `--`, `;i`, `;j`,
  `;++`, `;--`, `++)` 4.5.
- the loop variable right after `for` with no parenthesis (Go, Python style): `i`, `_`, `_,` 5.
- inside a `while (...)` condition: `<`, `<=`, `!=` 8.
Anything else: 0. A loop header counts only if no brace, closing paren or newline
lies between its `for` / `while` keyword and the token.
"""

READS = ()

IMPORT_ROOT = {"java": 9.0, "React": 12.0, "javax": 6.0, "com": 1.5, "org": 1.5}
HEADER_VAR = {"i": 6.0, "j": 3.0, "x": 2.0}
STEP = {"++", "--", "++)", ";i", ";j", ";++", ";--"}


def loop_header(raw):
    """('for' or 'while', whether a ';' comes after the keyword), or (None, False)
    when the newest token is not inside an open loop header."""
    for k in range(len(raw) - 2, -1, -1):
        word = raw[k].strip()
        if any(c in raw[k] for c in "{})\n"):
            return None, False
        if word in ("for", "while"):
            between = "".join(raw[k + 1 :])
            if word == "while" or "(" in between or ";" in between:
                return word, ";" in between
            return None, False
    return None, False


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-30:]
    docs = prefix.document_ids[-30:]
    cur = raw[-1]
    word = cur.strip()
    prev = raw[-2].strip() if len(raw) > 1 and docs[-2] == docs[-1] else ""
    if prev.endswith("include") and cur.lstrip().startswith("<"):
        return None, 11.0
    if prev == "import" and word in IMPORT_ROOT:
        return None, IMPORT_ROOT[word]
    if prev == "err" and word == "!=":
        return None, 6.0
    if word == ".com" and prev == "github":
        return None, 2.0
    if word == "://" and prev in ("http", "https"):
        return None, 1.25
    kind, after_semicolon = loop_header(raw)
    if kind == "for":
        if word.startswith(("<", "!=")):
            return None, 14.0 if after_semicolon else 6.0
        if word == ">" and after_semicolon:
            return None, 6.0
        if word in STEP:
            return None, 4.5
        if word == ";":
            return None, 1.0
        if word == "i" and not cur.startswith(" "):
            return None, 2.0
        if word in HEADER_VAR:
            return None, HEADER_VAR[word]
    if kind == "while" and word.startswith(("<", "!=")):
        return None, 8.0
    if prev == "for" and word in ("i", "_,", "_"):
        return None, 5.0
    return None, 0.0

programs.sol:
"""Partial lexical and formatting model, without a single semantic theme.

Document-initial articles and punctuation are biased negative, title case
positive. Hash-only and block-comment-opening tokens have larger negatives;
exact 'package' and 'namespace' tokens have opposite signs at document starts.
Elsewhere, small function-word and Chinese punctuation offsets are used,
plus negatives for exact 温/溫 and 敲 tokens. Chat/document delimiter tokens
have their own offsets. Many unrelated rare lexical responses are omitted.
"""
import unicodedata

READS = ()
ARTICLES = {'a', 'an', 'the'}
COPULAS = {'is', 'am', 'are', 'was', 'were', 'be', 'being', 'been'}
PRONOUNS = set('i me my mine you your yours he him his she her hers '
               'we us our ours they them their theirs it its'.split())


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip()
    lower = w.lower()
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if s == '<|im_start|>':
        return None, 0.139 if first else 0.058
    if s == '<|im_end|>' and not first:
        return None, 0.054
    if s == '<|endoftext|>':
        return None, -1.566 if first else -0.008
    if first:
        if w and set(w) == {'#'}:
            return None, -0.67
        if w.startswith('/*'):
            return None, -0.66
        if s == 'package':
            return None, 0.70
        if s == 'namespace':
            return None, -1.60
        value = -0.022 + 0.103 * w.istitle()
        if lower in ARTICLES:
            value -= 0.331
        if w and all(unicodedata.category(c).startswith('P') for c in w):
            value -= 0.137
        return None, value

    if s in ('温', '溫'):
        return None, -0.15
    if s == '敲':
        return None, -0.75
    if s == '，':
        return None, 0.023
    if s in ('。', '。\n'):
        return None, -0.04
    value = 0.001
    if lower in COPULAS:
        value += 0.009
    if lower in PRONOUNS:
        value += 0.008
    return None, value
